export const flashcardsData = [
  // ==========================================
  // NÍVEL A1 (1 - 20)
  // ==========================================
  { id: 'f1', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Water"?', back: 'Água.\n\nDica de Prática: "I drink water every day." (Eu bebo água todos os dias).' },
  { id: 'f2', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Cachorro" e "Gato"?', back: 'Dog (Cachorro) / Cat (Gato).\n\nDica de Prática: "My dog is playing with the cat."' },
  { id: 'f3', level: 'A1', theme: 'Grammar', front: 'Qual é o verbo "Ser/Estar" para "I" (Eu)?', back: 'Am.\n\nDica de Prática: "I am happy" (Eu estou feliz).' },
  { id: 'f4', level: 'A1', theme: 'Grammar', front: 'Qual é o verbo "Ser/Estar" para "He/She/It"?', back: 'Is.\n\nDica de Prática: "She is my friend" (Ela é minha amiga).' },
  { id: 'f5', level: 'A1', theme: 'Grammar', front: 'Qual é o verbo "Ser/Estar" para "You/We/They"?', back: 'Are.\n\nDica de Prática: "We are students" (Nós somos estudantes).' },
  { id: 'f6', level: 'A1', theme: 'Vocabulary', front: 'O que significa "House"?', back: 'Casa.\n\nDica de Prática: "This is my house" (Esta é a minha casa).' },
  { id: 'f7', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Livro"?', back: 'Book.\n\nDica de Prática: "I read a book" (Eu leio um livro).' },
  { id: 'f8', level: 'A1', theme: 'Daily Routine', front: 'O que significa "Eat"?', back: 'Comer.\n\nDica de Prática: "I eat an apple" (Eu como uma maçã).' },
  { id: 'f9', level: 'A1', theme: 'Daily Routine', front: 'O que significa "Sleep"?', back: 'Dormir.\n\nDica de Prática: "I sleep at night" (Eu durmo à noite).' },
  { id: 'f10', level: 'A1', theme: 'Vocabulary', front: 'Quais são as cores "Red", "Blue" e "Green"?', back: 'Vermelho, Azul e Verde.\n\nDica de Prática: "The sky is blue."' },
  { id: 'f11', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Hoje" e "Amanhã"?', back: 'Today (Hoje) / Tomorrow (Amanhã).\n\nDica de Prática: "See you tomorrow!" (Até amanhã!).' },
  { id: 'f12', level: 'A1', theme: 'Grammar', front: 'Como negar a frase "I like pizza"?', back: 'I do not (don\'t) like pizza.\n\nDica de Prática: Use "don\'t" para I/You/We/They.' },
  { id: 'f13', level: 'A1', theme: 'Grammar', front: 'Como negar a frase "She likes pizza"?', back: 'She does not (doesn\'t) like pizza.\n\nDica de Prática: Use "doesn\'t" para He/She/It.' },
  { id: 'f14', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Always"?', back: 'Sempre.\n\nDica de Prática: "I always wake up early" (Eu acordo sempre cedo).' },
  { id: 'f15', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Never"?', back: 'Nunca.\n\nDica de Prática: "I never drink coffee" (Eu nunca bebo café).' },
  { id: 'f16', level: 'A1', theme: 'Daily Routine', front: 'Como se diz "Trabalhar"?', back: 'Work.\n\nDica de Prática: "I work in an office" (Eu trabalho num escritório).' },
  { id: 'f17', level: 'A1', theme: 'Daily Routine', front: 'O que significa "Study"?', back: 'Estudar.\n\nDica de Prática: "I study English every day" (Eu estudo inglês todos os dias).' },
  { id: 'f18', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Dinheiro"?', back: 'Money.\n\nDica de Prática: "I don\'t have money" (Eu não tenho dinheiro).' },
  { id: 'f19', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Time"?', back: 'Tempo ou Hora.\n\nDica de Prática: "What time is it?" (Que horas são?).' },
  { id: 'f20', level: 'A1', theme: 'Vocabulary', front: 'Como dizer "Obrigado" e "De nada"?', back: 'Thank you / You\'re welcome.\n\nDica de Prática: Sempre que alguém agradecer, responda "You\'re welcome".' },

  // ==========================================
  // NÍVEL A2 (21 - 40)
  // ==========================================
  { id: 'f21', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Go" (Ir)?', back: 'Went.\n\nDica de Prática: "I went to the park yesterday" (Eu fui ao parque ontem).' },
  { id: 'f22', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Eat" (Comer)?', back: 'Ate.\n\nDica de Prática: "I ate a pizza for dinner" (Eu comi uma pizza ao jantar).' },
  { id: 'f23', level: 'A2', theme: 'Grammar', front: 'Como formar perguntas no passado simples?', back: 'Use o auxiliar "Did".\n\nDica de Prática: "Did you watch the movie?" (Viste o filme?). O verbo principal não muda!' },
  { id: 'f24', level: 'A2', theme: 'Phrasal Verbs', front: 'O que significa "Wake up"?', back: 'Acordar.\n\nDica de Prática: "I wake up at 7 AM" (Eu acordo às 7 da manhã).' },
  { id: 'f25', level: 'A2', theme: 'Phrasal Verbs', front: 'O que significa "Get up"?', back: 'Levantar-se (da cama/cadeira).\n\nDica de Prática: "I wake up at 7, but I get up at 7:15".' },
  { id: 'f26', level: 'A2', theme: 'Grammar', front: 'Como dizer que algo é "maior que" outra coisa?', back: 'Bigger than.\n\nDica de Prática: "My house is bigger than yours" (A minha casa é maior que a tua).' },
  { id: 'f27', level: 'A2', theme: 'Grammar', front: 'Como dizer que algo é "mais caro que" outra coisa?', back: 'More expensive than.\n\nDica de Prática: Adjetivos longos usam "more". Ex: "A car is more expensive than a bike".' },
  { id: 'f28', level: 'A2', theme: 'Prepositions', front: 'Quando usamos a preposição "IN" para tempo?', back: 'Para meses, anos e estações do ano.\n\nDica de Prática: "In May", "In 2026", "In winter".' },
  { id: 'f29', level: 'A2', theme: 'Prepositions', front: 'Quando usamos a preposição "ON" para tempo?', back: 'Para dias da semana e datas específicas.\n\nDica de Prática: "On Monday", "On May 15th".' },
  { id: 'f30', level: 'A2', theme: 'Prepositions', front: 'Quando usamos a preposição "AT" para tempo?', back: 'Para horas exatas e períodos específicos.\n\nDica de Prática: "At 3 PM", "At night", "At the weekend".' },
  { id: 'f31', level: 'A2', theme: 'Vocabulary', front: 'Qual é o oposto de "Fast" (Rápido)?', back: 'Slow (Lento).\n\nDica de Prática: "Turtles are very slow" (As tartarugas são muito lentas).' },
  { id: 'f32', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Buy" e "Sell"?', back: 'Buy (Comprar) / Sell (Vender).\n\nDica de Prática: "I want to buy a car, so I need to sell my bike".' },
  { id: 'f33', level: 'A2', theme: 'Grammar', front: 'Como expressar planos para o futuro usando "going to"?', back: 'Verb to be + going to + verb.\n\nDica de Prática: "I am going to travel tomorrow" (Eu vou viajar amanhã).' },
  { id: 'f34', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Understand"?', back: 'Entender / Compreender.\n\nDica de Prática: "I don\'t understand this question".' },
  { id: 'f35', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Esquecer"?', back: 'Forget.\n\nDica de Prática: "Don\'t forget your keys!" (Não te esqueças das chaves!).' },
  { id: 'f36', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Library" vs "Bookshop"?', back: 'Library = Biblioteca (requisitar livros). Bookshop = Livraria (comprar livros).\n\nDica de Prática: É um falso amigo comum em inglês!' },
  { id: 'f37', level: 'A2', theme: 'Daily Routine', front: 'Como se diz "Tomar banho"?', back: 'Take a shower (ou have a shower).\n\nDica de Prática: "I take a shower every morning".' },
  { id: 'f38', level: 'A2', theme: 'Grammar', front: 'Qual é a diferença entre "Some" e "Any"?', back: 'Some = Frases afirmativas. Any = Perguntas e Negativas.\n\nDica de Prática: "I have some water" vs "Do you have any water?".' },
  { id: 'f39', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Médico" e "Enfermeiro"?', back: 'Doctor / Nurse.\n\nDica de Prática: "The doctor and the nurse work in the hospital".' },
  { id: 'f40', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Tired"?', back: 'Cansado.\n\nDica de Prática: "I worked all day, I am very tired".' },

  // ==========================================
  // NÍVEL B1 (41 - 60)
  // ==========================================
  { id: 'f41', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Give up"?', back: 'Desistir ou parar um hábito.\n\nDica de Prática: "I want to give up smoking" (Eu quero deixar de fumar).' },
  { id: 'f42', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Take off"?', back: 'Descolar (avião) ou tirar uma peça de roupa.\n\nDica de Prática: "Take off your shoes" / "The plane will take off soon".' },
  { id: 'f43', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Look for"?', back: 'Procurar (algo ou alguém).\n\nDica de Prática: "I am looking for my keys" (Estou à procura das minhas chaves).' },
  { id: 'f44', level: 'B1', theme: 'Grammar', front: 'Quando usamos o "Present Perfect" (Have/Has + Particípio)?', back: 'Para ações passadas com foco no resultado presente, ou experiências sem tempo definido.\n\nDica de Prática: "I have lost my wallet" (Perdi a carteira e ainda não a encontrei).' },
  { id: 'f45', level: 'B1', theme: 'Grammar', front: 'Para que serve o verbo modal "Should"?', back: 'Dar conselhos ou recomendações.\n\nDica de Prática: "You should see a doctor" (Devias ir ao médico).' },
  { id: 'f46', level: 'B1', theme: 'Grammar', front: 'Qual é a diferença entre "Must" e "Have to"?', back: 'Must = Obrigação interna/pessoal. Have to = Obrigação externa/regra.\n\nDica de Prática: "I must study more" vs "You have to wear a uniform".' },
  { id: 'f47', level: 'B1', theme: 'Vocabulary', front: 'Diferença entre "Boring" e "Bored"?', back: 'Boring = Aborrecido (a causa). Bored = Aborrecido (o sentimento).\n\nDica de Prática: "The movie is boring, so I am bored".' },
  { id: 'f48', level: 'B1', theme: 'Vocabulary', front: 'Diferença entre "Borrow" e "Lend"?', back: 'Borrow = Pedir emprestado. Lend = Emprestar (a alguém).\n\nDica de Prática: "Can I borrow your pen?" / "Can you lend me your pen?".' },
  { id: 'f49', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Earn" vs "Spend"?', back: 'Earn = Ganhar (dinheiro pelo trabalho). Spend = Gastar (dinheiro ou tempo).\n\nDica de Prática: "I earn $2000, but I spend $1500".' },
  { id: 'f50', level: 'B1', theme: 'Grammar', front: 'Como se forma a 1ª Condicional (First Conditional)?', back: 'If + Present Simple, ... will + infinitive.\n\nDica de Prática: "If it rains, I will stay at home" (Possibilidade real no futuro).' },
  { id: 'f51', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Successful"?', back: 'Bem-sucedido.\n\nDica de Prática: "He is a successful businessman".' },
  { id: 'f52', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Fail"?', back: 'Falhar / Reprovar.\n\nDica de Prática: "If you don\'t study, you will fail the exam".' },
  { id: 'f53', level: 'B1', theme: 'Collocations', front: 'Diz-se "Make a mistake" ou "Do a mistake"?', back: 'Make a mistake (Cometer um erro).\n\nDica de Prática: "I made a mistake in the test".' },
  { id: 'f54', level: 'B1', theme: 'Collocations', front: 'Diz-se "Make homework" ou "Do homework"?', back: 'Do homework (Fazer os trabalhos de casa).\n\nDica de Prática: "I must do my homework".' },
  { id: 'f55', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Careful" e "Careless"?', back: 'Careful = Cuidadoso. Careless = Descuidado.\n\nDica de Prática: "Be careful when you cross the street".' },
  { id: 'f56', level: 'B1', theme: 'Grammar', front: 'Para que serve a "Voz Passiva" (Passive Voice)?', back: 'Para focar na ação ou no objeto que a sofreu, não em quem a fez.\n\nDica de Prática: "The window was broken" (A janela foi partida).' },
  { id: 'f57', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Arrive" e "Depart"?', back: 'Arrive = Chegar. Depart = Partir (voo, comboio).\n\nDica de Prática: "The train departs at 6 PM".' },
  { id: 'f58', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Look forward to"?', back: 'Ansiar por algo / Aguardar com expectativa.\n\nDica de Prática: "I look forward to the weekend". (Atenção: se usar verbo depois, leva -ing).' },
  { id: 'f59', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Find out"?', back: 'Descobrir (informação).\n\nDica de Prática: "I need to find out what happened".' },
  { id: 'f60', level: 'B1', theme: 'Grammar', front: 'Qual é o uso do "Past Continuous" (was/were + ing)?', back: 'Uma ação que estava a decorrer no passado e foi interrompida.\n\nDica de Prática: "I was sleeping when the phone rang".' },

  // ==========================================
  // NÍVEL B2 (61 - 80)
  // ==========================================
  { id: 'f61', level: 'B2', theme: 'Grammar', front: 'Como se forma a 2ª Condicional (Second Conditional)?', back: 'If + Past Simple, ... would + infinitive.\n\nDica de Prática: "If I won the lottery, I would buy a island" (Situação hipotética/irreal no presente).' },
  { id: 'f62', level: 'B2', theme: 'Grammar', front: 'Na 2ª Condicional com o verbo "To Be", qual é a forma para "I"?', back: 'Were (If I were you).\n\nDica de Prática: "If I were you, I would study more" (Se eu fosse a ti, estudava mais).' },
  { id: 'f63', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Put off"?', back: 'Adiar (postpone).\n\nDica de Prática: "We had to put off the meeting until tomorrow".' },
  { id: 'f64', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Call off"?', back: 'Cancelar (cancel).\n\nDica de Prática: "The concert was called off due to rain".' },
  { id: 'f65', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Figure out"?', back: 'Compreender / Resolver um problema mentalmente.\n\nDica de Prática: "I can\'t figure out how this machine works".' },
  { id: 'f66', level: 'B2', theme: 'Idioms', front: 'O que significa a expressão "A piece of cake"?', back: 'Algo muito fácil.\n\nDica de Prática: "The English test was a piece of cake".' },
  { id: 'f67', level: 'B2', theme: 'Idioms', front: 'O que significa "Out of the blue"?', back: 'Inesperadamente / Do nada.\n\nDica de Prática: "He called me completely out of the blue".' },
  { id: 'f68', level: 'B2', theme: 'Collocations', front: 'O que significa "Take advantage of"?', back: 'Tirar partido de / Aproveitar uma oportunidade.\n\nDica de Prática: "You should take advantage of this discount".' },
  { id: 'f69', level: 'B2', theme: 'Collocations', front: 'O que significa "Make up your mind"?', back: 'Decidir-se / Tomar uma decisão.\n\nDica de Prática: "I can\'t make up my mind between the blue or red shirt".' },
  { id: 'f70', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Stubborn"?', back: 'Teimoso.\n\nDica de Prática: "He never listens to advice; he is very stubborn".' },
  { id: 'f71', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Reliable"?', back: 'Fiável / De confiança.\n\nDica de Prática: "My new car is very reliable; it never breaks down".' },
  { id: 'f72', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Break down"?', back: 'Avariar (máquina) ou ter um colapso emocional.\n\nDica de Prática: "My car broke down on the highway".' },
  { id: 'f73', level: 'B2', theme: 'Vocabulary', front: 'O que é um "Breakthrough"?', back: 'Um avanço importante / Descoberta inovadora.\n\nDica de Prática: "Scientists made a major breakthrough in cancer research".' },
  { id: 'f74', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Come up with"?', back: 'Inventar / Ter uma ideia.\n\nDica de Prática: "We need to come up with a new marketing strategy".' },
  { id: 'f75', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Run out of"?', back: 'Ficar sem (esgotar stock).\n\nDica de Prática: "We have run out of milk. We need to buy more".' },
  { id: 'f76', level: 'B2', theme: 'Grammar', front: 'O que é o "Past Perfect" (had + particípio)?', back: 'O "passado do passado". Ação que aconteceu antes de outra no passado.\n\nDica de Prática: "When I arrived, the train had left" (O comboio partiu antes de eu chegar).' },
  { id: 'f77', level: 'B2', theme: 'Grammar', front: 'Como usar a estrutura causativa "Get something done"?', back: 'Indica que arranjou alguém para fazer um serviço para si.\n\nDica de Prática: "I need to get my hair cut" (Cortar o cabelo no cabeleireiro).' },
  { id: 'f78', level: 'B2', theme: 'Collocations', front: 'Diz-se "Deal with" ou "Deal about"?', back: 'Deal with (Lidar com).\n\nDica de Prática: "I have to deal with many difficult customers".' },
  { id: 'f79', level: 'B2', theme: 'Grammar', front: 'Como expressar arrependimento no passado com "Wish"?', back: 'Wish + Past Perfect.\n\nDica de Prática: "I wish I had studied more" (Quem me dera ter estudado mais).' },
  { id: 'f80', level: 'B2', theme: 'Collocations', front: 'O que significa "By the way"?', back: 'Por falar nisso / A propósito.\n\nDica de Prática: "By the way, did you see the email I sent?".' },

  // ==========================================
  // NÍVEL C1 (81 - 100)
  // ==========================================
  { id: 'f81', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ephemeral"?', back: 'Efémero, que dura muito pouco tempo.\n\nDica de Prática: "Fame on the internet is often ephemeral".' },
  { id: 'f82', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ubiquitous"?', back: 'Omnipresente, que está em todo o lado.\n\nDica de Prática: "Smartphones are ubiquitous in modern society".' },
  { id: 'f83', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Mitigate"?', back: 'Atenuar, reduzir a gravidade de algo.\n\nDica de Prática: "We must take action to mitigate the effects of climate change".' },
  { id: 'f84', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Elucidate"?', back: 'Explicar de forma clara, clarificar (formal).\n\nDica de Prática: "Could you elucidate your theory, please?".' },
  { id: 'f85', level: 'C1', theme: 'Idioms', front: 'O que significa "Burn your bridges"?', back: 'Queimar pontes (destruir relações ou a possibilidade de retorno).\n\nDica de Prática: "Don\'t burn your bridges when you leave your job".' },
  { id: 'f86', level: 'C1', theme: 'Idioms', front: 'O que significa "Play devil\'s advocate"?', back: 'Fazer de advogado do diabo (defender um lado contrário apenas para estimular o debate).\n\nDica de Prática: "I agree with you, I\'m just playing devil\'s advocate".' },
  { id: 'f87', level: 'C1', theme: 'Idioms', front: 'O que significa "Bite the bullet"?', back: 'Enfrentar uma situação difícil ou dolorosa com coragem (porque é inevitável).\n\nDica de Prática: "I hate going to the dentist, but I\'ll just have to bite the bullet".' },
  { id: 'f88', level: 'C1', theme: 'Idioms', front: 'O que significa estar "Dead in the water"?', back: 'Estar paralisado, sem hipótese de avançar ou ter sucesso.\n\nDica de Prática: "Without funding, the project is dead in the water".' },
  { id: 'f89', level: 'C1', theme: 'Collocations', front: 'O que significa a expressão "Stark contrast"?', back: 'Um contraste muito acentuado e evidente.\n\nDica de Prática: "His wealth is in stark contrast to the poverty around him".' },
  { id: 'f90', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Incomprehensible"?', back: 'Incompreensível, impossível de entender.\n\nDica de Prática: "His mumbling was totally incomprehensible".' },
  { id: 'f91', level: 'C1', theme: 'Grammar', front: 'Como funciona a inversão com "Hardly" ou "Scarcely"?', back: 'Exige inversão do sujeito e auxiliar: Hardly + had + sujeito + particípio.\n\nDica de Prática: "Hardly had I arrived when it started raining".' },
  { id: 'f92', level: 'C1', theme: 'Vocabulary', front: 'O que é uma "Epiphany"?', back: 'Uma epifania, um momento súbito de revelação ou compreensão profunda.\n\nDica de Prática: "She had an epiphany about her career path".' },
  { id: 'f93', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Derogatory"?', back: 'Depreciativo, ofensivo ou que demonstra desrespeito.\n\nDica de Prática: "He made a derogatory comment about her work".' },
  { id: 'f94', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ascertain"?', back: 'Apurar, certificar-se ou descobrir a verdade (formal).\n\nDica de Prática: "We need to ascertain the cause of the fire".' },
  { id: 'f95', level: 'C1', theme: 'Vocabulary', front: 'Diferença entre "Surge" e "Plunge"?', back: 'Surge = Aumento forte e súbito. Plunge = Queda abrupta.\n\nDica de Prática: "Stock prices surged, then plunged the next day".' },
  { id: 'f96', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Defuse"?', back: 'Desarmar (literalmente) ou acalmar uma situação tensa.\n\nDica de Prática: "The manager managed to defuse the argument between the employees".' },
  { id: 'f97', level: 'C1', theme: 'Grammar', front: 'O que é o Subjuntivo em Inglês (ex: after "crucial")?', back: 'Usa-se a forma base do verbo (sem "to" ou "s") após expressões de importância.\n\nDica de Prática: "It is crucial that he BE here" (e não "is").' },
  { id: 'f98', level: 'C1', theme: 'Vocabulary', front: 'Atenção ao falso cognato: "Ignorant" em inglês significa o quê?', back: 'Significa falta de conhecimento sobre algo (ignorante no sentido de não saber), não necessariamente "mal-educado" como no português.\n\nDica de Prática: "I am completely ignorant about quantum physics".' },
  { id: 'f99', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Acknowledge"?', back: 'Reconhecer (um erro, um facto) ou acusar a receção.\n\nDica de Prática: "He refused to acknowledge his mistake".' },
  { id: 'f100', level: 'C1', theme: 'Grammar', front: 'Como formar a "Mixed Conditional" (Passado -> Presente)?', back: 'If + Past Perfect, ... would + infinitive.\n\nDica de Prática: "If I had studied medicine, I would be a doctor now".' },
  // ==========================================
  // NÍVEL A1 (101 - 120)
  // ==========================================
  { id: 'f101', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Mãe" e "Pai"?', back: 'Mother / Father (ou Mom / Dad).\n\nDica de Prática: "My mother and father are at home".' },
  { id: 'f102', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Irmão" e "Irmã"?', back: 'Brother / Sister.\n\nDica de Prática: "I have one brother and two sisters".' },
  { id: 'f103', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Sunny" e "Rainy"?', back: 'Ensolarado / Chuvoso.\n\nDica de Prática: "Today is a sunny day" (Hoje é um dia ensolarado).' },
  { id: 'f104', level: 'A1', theme: 'Vocabulary', front: 'Como dizer que está "Quente" ou "Frio"?', back: 'Hot / Cold.\n\nDica de Prática: "It is very cold today" (Está muito frio hoje).' },
  { id: 'f105', level: 'A1', theme: 'Vocabulary', front: 'Quais são os dias "Monday" e "Friday"?', back: 'Segunda-feira e Sexta-feira.\n\nDica de Prática: "I work from Monday to Friday".' },
  { id: 'f106', level: 'A1', theme: 'Grammar', front: 'O que significam as question words "Who" e "Where"?', back: 'Quem / Onde.\n\nDica de Prática: "Who is he?" e "Where do you live?".' },
  { id: 'f107', level: 'A1', theme: 'Grammar', front: 'O que significam as question words "When" e "Why"?', back: 'Quando / Porquê.\n\nDica de Prática: "When is your birthday?" e "Why are you sad?".' },
  { id: 'f108', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Pão" e "Leite"?', back: 'Bread / Milk.\n\nDica de Prática: "I eat bread and drink milk for breakfast".' },
  { id: 'f109', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Bird" e "Fish"?', back: 'Pássaro / Peixe.\n\nDica de Prática: "The bird is in the sky and the fish is in the water".' },
  { id: 'f110', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Cabeça" e "Mãos"?', back: 'Head / Hands.\n\nDica de Prática: "Wash your hands before eating".' },
  { id: 'f111', level: 'A1', theme: 'Vocabulary', front: 'O que significam os verbos "Run" e "Walk"?', back: 'Correr / Andar (Caminhar).\n\nDica de Prática: "I walk to school, but I run in the park".' },
  { id: 'f112', level: 'A1', theme: 'Vocabulary', front: 'O que significam os verbos "Speak" e "Listen"?', back: 'Falar / Ouvir.\n\nDica de Prática: "I speak English and listen to music".' },
  { id: 'f113', level: 'A1', theme: 'Vocabulary', front: 'Como se diz os números 20 e 30?', back: 'Twenty (20) / Thirty (30).\n\nDica de Prática: "I am twenty years old".' },
  { id: 'f114', level: 'A1', theme: 'Vocabulary', front: 'Quais são as cores "Yellow" e "Black"?', back: 'Amarelo e Preto.\n\nDica de Prática: "The taxi is yellow and black".' },
  { id: 'f115', level: 'A1', theme: 'Prepositions', front: 'Qual a diferença básica de lugar entre "IN" e "ON"?', back: 'IN = Dentro de. ON = Em cima de (superfície).\n\nDica de Prática: "The book is ON the table, the pen is IN the box".' },
  { id: 'f116', level: 'A1', theme: 'Prepositions', front: 'O que significa "Under" e "Next to"?', back: 'Debaixo de / Ao lado de.\n\nDica de Prática: "The cat is under the bed".' },
  { id: 'f117', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Camisa" e "Sapatos"?', back: 'Shirt / Shoes.\n\nDica de Prática: "I am wearing a blue shirt and black shoes".' },
  { id: 'f118', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Cozinha" e "Quarto"?', back: 'Kitchen / Bedroom.\n\nDica de Prática: "I cook in the kitchen and sleep in the bedroom".' },
  { id: 'f119', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Big" e "Small"?', back: 'Grande / Pequeno.\n\nDica de Prática: "The elephant is big, the mouse is small".' },
  { id: 'f120', level: 'A1', theme: 'Vocabulary', front: 'Qual é o oposto de "Good" (Bom)?', back: 'Bad (Mau/Ruim).\n\nDica de Prática: "This is a good book, but that movie is bad".' },

  // ==========================================
  // NÍVEL A2 (121 - 140)
  // ==========================================
  { id: 'f121', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "See" (Ver)?', back: 'Saw.\n\nDica de Prática: "I saw my friend at the mall yesterday".' },
  { id: 'f122', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Make" (Fazer)?', back: 'Made.\n\nDica de Prática: "She made a delicious cake for my birthday".' },
  { id: 'f123', level: 'A2', theme: 'Grammar', front: 'Como se diz "Melhor que" e "Pior que"?', back: 'Better than / Worse than.\n\nDica de Prática: "Today the weather is better than yesterday".' },
  { id: 'f124', level: 'A2', theme: 'Grammar', front: 'Como se diz "O melhor" e "O pior" (Superlativo)?', back: 'The best / The worst.\n\nDica de Prática: "This is the best movie I have ever seen".' },
  { id: 'f125', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Flight" e "Luggage"?', back: 'Voo / Bagagem.\n\nDica de Prática: "My flight is delayed and I lost my luggage".' },
  { id: 'f126', level: 'A2', theme: 'Phrasal Verbs', front: 'O que significa "Turn on" e "Turn off"?', back: 'Ligar / Desligar (aparelhos eletrónicos).\n\nDica de Prática: "Please turn off the lights when you leave".' },
  { id: 'f127', level: 'A2', theme: 'Phrasal Verbs', front: 'O que significa "Put on"?', back: 'Vestir ou calçar.\n\nDica de Prática: "It\'s cold, put on your jacket".' },
  { id: 'f128', level: 'A2', theme: 'Grammar', front: 'Quando usamos "Will" em vez de "Going to"?', back: 'Will: Decisões no momento ou promessas. Going to: Planos pré-definidos.\n\nDica de Prática: "I am going to travel next week. / Oh, I will help you pack!".' },
  { id: 'f129', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Receipt" e "Price"?', back: 'Recibo (talão) / Preço.\n\nDica de Prática: "Keep the receipt if you want to change the shirt".' },
  { id: 'f130', level: 'A2', theme: 'Grammar', front: 'Qual a diferença entre "How much" e "How many"?', back: 'Much = Incontáveis (água, tempo). Many = Contáveis (livros, dias).\n\nDica de Prática: "How much time do we have?" vs "How many apples do you want?".' },
  { id: 'f131', level: 'A2', theme: 'Grammar', front: 'Qual a diferença entre "A few" e "A little"?', back: 'A few = Alguns (para contáveis). A little = Um pouco (para incontáveis).\n\nDica de Prática: "I have a few friends" vs "I need a little sugar".' },
  { id: 'f132', level: 'A2', theme: 'Vocabulary', front: 'Como dar direções: "Vire à esquerda" e "Siga em frente"?', back: 'Turn left / Go straight on.\n\nDica de Prática: "Go straight on and turn left at the corner".' },
  { id: 'f133', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Bring" e "Take"?', back: 'Bring = Trazer (para aqui). Take = Levar (para lá).\n\nDica de Prática: "Take this book to the library, and bring me a new one".' },
  { id: 'f134', level: 'A2', theme: 'Grammar', front: 'Qual a diferença entre "I played" e "I was playing"?', back: 'I played = Eu joguei (ação terminada). I was playing = Eu estava a jogar (ação em curso no passado).\n\nDica de Prática: "I was playing when it started to rain".' },
  { id: 'f135', level: 'A2', theme: 'Grammar', front: 'Diferença entre os modais "Can" e "Could"?', back: 'Can = Posso/Consigo (presente). Could = Podia/Conseguia (passado ou pedido educado).\n\nDica de Prática: "Could you open the door, please?".' },
  { id: 'f136', level: 'A2', theme: 'Vocabulary', front: 'O que significam os hobbies "Drawing" e "Gardening"?', back: 'Desenhar / Jardinagem.\n\nDica de Prática: "In my free time, I like drawing".' },
  { id: 'f137', level: 'A2', theme: 'Vocabulary', front: 'Como dizer "Dor de cabeça" e "Dor de estômago"?', back: 'Headache / Stomachache.\n\nDica de Prática: "I need an aspirin, I have a terrible headache".' },
  { id: 'f138', level: 'A2', theme: 'Grammar', front: 'Diferença entre "Because" e "So"?', back: 'Because = Porque (causa). So = Então/Por isso (consequência).\n\nDica de Prática: "I didn\'t go out because it was raining. It was raining, so I didn\'t go out".' },
  { id: 'f139', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Interesting" e "Interested"?', back: 'Interesting = Interessante (a coisa). Interested = Interessado (a pessoa).\n\nDica de Prática: "This book is interesting, I am interested in it".' },
  { id: 'f140', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Professor" e "Engenheiro"?', back: 'Teacher / Engineer.\n\nDica de Prática: "My mom is a teacher and my dad is an engineer".' },

  // ==========================================
  // NÍVEL B1 (141 - 160)
  // ==========================================
  { id: 'f141', level: 'B1', theme: 'Grammar', front: 'Para que serve a palavra "Just" no Present Perfect?', back: 'Para indicar que uma ação aconteceu há pouquíssimo tempo.\n\nDica de Prática: "I have just finished my dinner" (Acabei mesmo agora o jantar).' },
  { id: 'f142', level: 'B1', theme: 'Grammar', front: 'Diferença entre "Already" e "Yet"?', back: 'Already = Já (afirmativas, algo aconteceu cedo). Yet = Já/Ainda (perguntas e negativas, no fim da frase).\n\nDica de Prática: "I have already eaten" vs "Have you eaten yet?".' },
  { id: 'f143', level: 'B1', theme: 'Grammar', front: 'No Present Perfect, quando usar "For" ou "Since"?', back: 'For = Duração/Período (For 2 years). Since = Ponto de partida (Since 2020).\n\nDica de Prática: "I have lived here for 5 years, since 2019".' },
  { id: 'f144', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Take up"?', back: 'Começar um novo hobby ou atividade.\n\nDica de Prática: "I want to take up photography this year".' },
  { id: 'f145', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Grow up"?', back: 'Crescer (referente a pessoas, passar de criança a adulto).\n\nDica de Prática: "I grew up in a small town in Brazil".' },
  { id: 'f146', level: 'B1', theme: 'Grammar', front: 'Para que servem os modais "Might" e "May"?', back: 'Para expressar possibilidade no presente ou futuro (talvez).\n\nDica de Prática: "Take an umbrella, it might rain later".' },
  { id: 'f147', level: 'B1', theme: 'Grammar', front: 'Como se forma a Voz Passiva no Presente?', back: 'Am/Is/Are + Particípio Passado do verbo.\n\nDica de Prática: "The office is cleaned every day" (O escritório é limpo todos os dias).' },
  { id: 'f148', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Apply for a job"?', back: 'Candidatar-se a um emprego.\n\nDica de Prática: "I decided to apply for the manager position".' },
  { id: 'f149', level: 'B1', theme: 'Collocations', front: 'Diz-se "Make business" ou "Do business"?', back: 'Do business (Fazer negócios).\n\nDica de Prática: "It\'s a pleasure to do business with your company".' },
  { id: 'f150', level: 'B1', theme: 'Grammar', front: 'Quando usar "Who", "Which" e "Whose"?', back: 'Who = Pessoas. Which = Coisas. Whose = Posse (cujo).\n\nDica de Prática: "The man whose car was stolen is talking to the police".' },
  { id: 'f151', level: 'B1', theme: 'Grammar', front: 'Para que serve a expressão "Used to"?', back: 'Para falar de hábitos do passado que já não acontecem.\n\nDica de Prática: "I used to play tennis when I was a child".' },
  { id: 'f152', level: 'B1', theme: 'Vocabulary', front: 'O que significam "Pollution" e "Recycle"?', back: 'Poluição / Reciclar.\n\nDica de Prática: "We must recycle plastic to reduce pollution".' },
  { id: 'f153', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Look after"?', back: 'Tomar conta de / Cuidar de.\n\nDica de Prática: "Can you look after my dog this weekend?".' },
  { id: 'f154', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Set up"?', back: 'Configurar, instalar ou fundar (uma empresa).\n\nDica de Prática: "I need to set up my new laptop".' },
  { id: 'f155', level: 'B1', theme: 'Grammar', front: 'Como formar a maioria dos advérbios de modo (ex: quick, slow)?', back: 'Adicionando "-ly" ao final do adjetivo (Quickly, Slowly).\n\nDica de Prática: "She speaks English very quickly".' },
  { id: 'f156', level: 'B1', theme: 'Grammar', front: 'Quando usar pronomes reflexivos como "Myself" ou "Yourself"?', back: 'Quando o sujeito e o objeto da ação são a mesma pessoa.\n\nDica de Prática: "I cut myself while cooking".' },
  { id: 'f157', level: 'B1', theme: 'Grammar', front: 'Como concordar com alguém dizendo "Eu também"?', back: 'So do I / Me too.\n\nDica de Prática: "I love pizza. - So do I!"' },
  { id: 'f158', level: 'B1', theme: 'Grammar', front: 'O que significam "Although" e "Even though"?', back: 'Embora / Apesar de (introduzem um contraste).\n\nDica de Prática: "Although it was raining, we went for a walk".' },
  { id: 'f159', level: 'B1', theme: 'Grammar', front: 'O que significa a conjunção "Unless"?', back: 'A não ser que / A menos que (If not).\n\nDica de Prática: "You will fail unless you study" (Reprovarás a menos que estudes).' },
  { id: 'f160', level: 'B1', theme: 'Vocabulary', front: 'O que significam "Sightseeing" e "Accommodation"?', back: 'Ver as vistas (turismo) / Alojamento.\n\nDica de Prática: "We paid for the flights and the accommodation".' },

  // ==========================================
  // NÍVEL B2 (161 - 180)
  // ==========================================
  { id: 'f161', level: 'B2', theme: 'Grammar', front: 'Como se forma a 3ª Condicional (Third Conditional)?', back: 'If + Past Perfect, ... would have + particípio.\n\nDica de Prática: "If I had known, I would have helped you" (Condição irreal no passado).' },
  { id: 'f162', level: 'B2', theme: 'Grammar', front: 'O que indica o Past Perfect Continuous (had been + ing)?', back: 'Uma ação contínua no passado que ocorreu antes de outra no passado.\n\nDica de Prática: "I had been waiting for an hour when the bus arrived".' },
  { id: 'f163', level: 'B2', theme: 'Grammar', front: 'Qual é a regra geral do "Reported Speech" (Discurso Indireto)?', back: 'O tempo verbal recua um tempo para o passado ("backshift").\n\nDica de Prática: "I like it" -> He said that he liked it.' },
  { id: 'f164', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Bring up"?', back: 'Criar (educar uma criança) ou trazer um assunto à baila.\n\nDica de Prática: "Don\'t bring up the budget during the meeting".' },
  { id: 'f165', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Turn down"?', back: 'Baixar o volume/temperatura ou recusar um convite/oferta.\n\nDica de Prática: "He turned down the job offer".' },
  { id: 'f166', level: 'B2', theme: 'Idioms', front: 'O que significa a expressão "Cost an arm and a leg"?', back: 'Custar os olhos da cara (ser caríssimo).\n\nDica de Prática: "I love that car, but it costs an arm and a leg".' },
  { id: 'f167', level: 'B2', theme: 'Idioms', front: 'O que significa estar "Under the weather"?', back: 'Sentir-se doente ou indisposto.\n\nDica de Prática: "I\'m not going to work today, I\'m feeling a bit under the weather".' },
  { id: 'f168', level: 'B2', theme: 'Collocations', front: 'O que significa "Bear in mind"?', back: 'Ter em mente / Lembrar-se de considerar algo.\n\nDica de Prática: "Bear in mind that the deadline is next Friday".' },
  { id: 'f169', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Overwhelmed"?', back: 'Sobrecarregado (emocionalmente ou de trabalho).\n\nDica de Prática: "I am feeling overwhelmed with all these new projects".' },
  { id: 'f170', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Reluctant"?', back: 'Relutante, sem vontade de fazer algo.\n\nDica de Prática: "She was reluctant to accept the manager\'s proposal".' },
  { id: 'f171', level: 'B2', theme: 'Grammar', front: 'Como usar "Wish" para desejar que algo fosse diferente no PRESENTE?', back: 'Wish + Past Simple.\n\nDica de Prática: "I wish I had more free time" (Quem me dera ter mais tempo livre).' },
  { id: 'f172', level: 'B2', theme: 'Grammar', front: 'Como usar "Wish" para reclamar do comportamento irritante de alguém?', back: 'Wish + would + verbo base.\n\nDica de Prática: "I wish you would stop tapping your pen".' },
  { id: 'f173', level: 'B2', theme: 'Grammar', front: 'Para que serve a estrutura "Should have + particípio"?', back: 'Para expressar arrependimento ou crítica sobre algo que (não) devia ter acontecido.\n\nDica de Prática: "You should have called me earlier" (Devias ter-me ligado mais cedo).' },
  { id: 'f174', level: 'B2', theme: 'Grammar', front: 'Para que serve a estrutura "Must have + particípio"?', back: 'Para fazer uma dedução lógica forte sobre o passado.\n\nDica de Prática: "The streets are wet. It must have rained last night".' },
  { id: 'f175', level: 'B2', theme: 'Grammar', front: 'Como usar "Despite" e "In spite of"?', back: 'Ambos significam "Apesar de". São seguidos por um substantivo ou verbo em -ing, NUNCA por "of" no caso do Despite.\n\nDica de Prática: "Despite the rain, we went out" (E não "Despite of").' },
  { id: 'f176', level: 'B2', theme: 'Grammar', front: 'Na ordem dos adjetivos, o que vem primeiro: Opinião ou Tamanho?', back: 'Opinião (ex: beautiful, ugly) vem antes do tamanho (ex: big, small).\n\nDica de Prática: "A beautiful big house".' },
  { id: 'f177', level: 'B2', theme: 'Vocabulary', front: 'O que significa o adjetivo "Breathtaking"?', back: 'Deslumbrante, de tirar o fôlego.\n\nDica de Prática: "The view from the top of the mountain was breathtaking".' },
  { id: 'f178', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Catch up with"?', back: 'Pôr a conversa em dia ou alcançar o nível de alguém.\n\nDica de Prática: "Let\'s get coffee and catch up!".' },
  { id: 'f179', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Put up with"?', back: 'Tolerar, suportar algo ou alguém irritante.\n\nDica de Prática: "I can\'t put up with this noise anymore".' },
  { id: 'f180', level: 'B2', theme: 'Collocations', front: 'O que significa "Take for granted"?', back: 'Dar como garantido / Não dar o devido valor.\n\nDica de Prática: "We often take our health for granted until we get sick".' },

  // ==========================================
  // NÍVEL C1 (181 - 200)
  // ==========================================
  { id: 'f181', level: 'C1', theme: 'Grammar', front: 'Como usar inversão com "Not only"?', back: 'O verbo auxiliar e o sujeito invertem-se após "Not only".\n\nDica de Prática: "Not only WAS HE late, but he also forgot the report".' },
  { id: 'f182', level: 'C1', theme: 'Grammar', front: 'Como se usa a estrutura "No sooner... than"?', back: 'Para dizer que uma ação aconteceu imediatamente após outra (com inversão no início).\n\nDica de Prática: "No sooner HAD I ARRIVED than the phone rang".' },
  { id: 'f183', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Meticulous"?', back: 'Extremamente cuidadoso com pequenos detalhes.\n\nDica de Prática: "He is meticulous in his research".' },
  { id: 'f184', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Deterrent"?', back: 'Dissuasor / Algo que desincentiva alguém de fazer algo.\n\nDica de Prática: "High fines act as a deterrent against speeding".' },
  { id: 'f185', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Plausible"?', back: 'Plausível, razoável ou provável.\n\nDica de Prática: "That seems like a plausible explanation for the error".' },
  { id: 'f186', level: 'C1', theme: 'Idioms', front: 'O que é "A blessing in disguise"?', back: 'Um mal que vem por bem (algo mau que acaba por ter um resultado positivo).\n\nDica de Prática: "Losing that job was a blessing in disguise".' },
  { id: 'f187', level: 'C1', theme: 'Idioms', front: 'O que significa "Beat around the bush"?', back: 'Andar com rodeios (não ir direto ao assunto).\n\nDica de Prática: "Stop beating around the bush and tell me the truth".' },
  { id: 'f188', level: 'C1', theme: 'Grammar', front: 'O que é uma "Cleft Sentence" com "It"?', back: 'Estrutura usada para dar forte ênfase a uma parte da frase (It was X that Y).\n\nDica de Prática: "It was JOHN who broke the window (não o Peter)".' },
  { id: 'f189', level: 'C1', theme: 'Grammar', front: 'Como usar uma "Cleft Sentence" com "What"?', back: 'Usada para enfatizar o que se sente ou precisa.\n\nDica de Prática: "What I need right now is a long holiday".' },
  { id: 'f190', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Boil down to"?', back: 'Resumir-se a / O ponto mais importante de uma situação.\n\nDica de Prática: "The problem boils down to a lack of money".' },
  { id: 'f191', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Fend for yourself"?', back: 'Cuidar de si mesmo sem a ajuda dos outros, desenrascar-se.\n\nDica de Prática: "When you go to university, you have to fend for yourself".' },
  { id: 'f192', level: 'C1', theme: 'Collocations', front: 'O que é "A heated debate"?', back: 'Um debate aceso/intenso, muitas vezes com vozes exaltadas.\n\nDica de Prática: "There was a heated debate about the new policy".' },
  { id: 'f193', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Exacerbate"?', back: 'Agravar ou piorar um problema/situação.\n\nDica de Prática: "His aggressive tone only exacerbated the conflict".' },
  { id: 'f194', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Quintessential"?', back: 'O exemplo perfeito ou mais típico de algo.\n\nDica de Prática: "Fish and chips is the quintessential British meal".' },
  { id: 'f195', level: 'C1', theme: 'Grammar', front: 'Qual é a diferença entre "Nevertheless" e "Nonetheless"?', back: 'Nenhuma. Ambos significam "Ainda assim / Não obstante" e são muito formais.\n\nDica de Prática: "It was raining. Nevertheless, we continued the match".' },
  { id: 'f196', level: 'C1', theme: 'Grammar', front: 'O que indica uma "Participle Clause" iniciada por "Having + particípio"?', back: 'Que a ação na cláusula terminou ANTES da ação da oração principal.\n\nDica de Prática: "Having finished my dinner, I went to sleep".' },
  { id: 'f197', level: 'C1', theme: 'Grammar', front: 'O que significa "Bound to"?', back: 'Algo que é certo, inevitável ou muito provável de acontecer.\n\nDica de Prática: "With all that studying, she is bound to pass the exam".' },
  { id: 'f198', level: 'C1', theme: 'Idioms', front: 'O que significa fazer algo "By the skin of your teeth"?', back: 'Conseguir algo à rasca (por um triz/cabelo).\n\nDica de Prática: "I passed the math exam by the skin of my teeth".' },
  { id: 'f199', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Scrutinize"?', back: 'Examinar ou inspecionar algo minuciosamente.\n\nDica de Prática: "The contract was heavily scrutinized by the lawyers".' },
  { id: 'f200', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Conducive"?', back: 'Favorável, que proporciona boas condições para que algo aconteça.\n\nDica de Prática: "A noisy environment is not conducive to studying".' },
  // ==========================================
  // NÍVEL A1 (201 - 220)
  // ==========================================
  { id: 'f201', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Tia" e "Tio"?', back: 'Aunt / Uncle.\n\nDica de Prática: "My aunt and uncle live in London".' },
  { id: 'f202', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Porco" e "Cavalo"?', back: 'Pig / Horse.\n\nDica de Prática: "The horse is big and the pig is pink".' },
  { id: 'f203', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Cheese" e "Butter"?', back: 'Queijo / Manteiga.\n\nDica de Prática: "I like bread with butter and cheese".' },
  { id: 'f204', level: 'A1', theme: 'Grammar', front: 'Qual é o verbo "Ter" (Have) para He/She/It?', back: 'Has.\n\nDica de Prática: "I have a car, but he has a bicycle".' },
  { id: 'f205', level: 'A1', theme: 'Grammar', front: 'O que significa "There is" e "There are"?', back: 'Há / Existe (no singular e no plural).\n\nDica de Prática: "There is a book on the table. There are two pens".' },
  { id: 'f206', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Morning" e "Evening"?', back: 'Manhã / Fim de tarde ou Noite (antes de dormir).\n\nDica de Prática: "I drink coffee in the morning".' },
  { id: 'f207', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Alto" e "Baixo" (para pessoas)?', back: 'Tall / Short.\n\nDica de Prática: "My brother is tall, but I am short".' },
  { id: 'f208', level: 'A1', theme: 'Vocabulary', front: 'O que significam "Happy" e "Sad"?', back: 'Feliz / Triste.\n\nDica de Prática: "She is happy today, but he is sad".' },
  { id: 'f209', level: 'A1', theme: 'Grammar', front: 'O que significam as perguntas "How?" e "How old?"', back: 'Como? / Que idade? (Quão velho?).\n\nDica de Prática: "How are you?" e "How old are you?".' },
  { id: 'f210', level: 'A1', theme: 'Prepositions', front: 'Como se diz "Em casa" e "No trabalho"?', back: 'At home / At work.\n\nDica de Prática: "I am not at work, I am at home".' },
  { id: 'f211', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Janela" e "Porta"?', back: 'Window / Door.\n\nDica de Prática: "Please, open the window and close the door".' },
  { id: 'f212', level: 'A1', theme: 'Vocabulary', front: 'O que significam os verbos "Drink" e "Eat"?', back: 'Beber / Comer.\n\nDica de Prática: "I eat an apple and drink water".' },
  { id: 'f213', level: 'A1', theme: 'Vocabulary', front: 'O que significam "Read" e "Write"?', back: 'Ler / Escrever.\n\nDica de Prática: "I read a book and write an email".' },
  { id: 'f214', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Calças" e "Vestido"?', back: 'Pants (ou Trousers) / Dress.\n\nDica de Prática: "She is wearing a red dress".' },
  { id: 'f215', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Olhos" e "Orelhas"?', back: 'Eyes / Ears.\n\nDica de Prática: "He has blue eyes".' },
  { id: 'f216', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Hospital" e "Escola"?', back: 'Hospital / School.\n\nDica de Prática: "The doctor works in the hospital".' },
  { id: 'f217', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Bus" e "Train"?', back: 'Autocarro (Ônibus) / Comboio (Trem).\n\nDica de Prática: "I go to work by bus".' },
  { id: 'f218', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Snow" e "Wind"?', back: 'Neve / Vento.\n\nDica de Prática: "Look at the snow outside!".' },
  { id: 'f219', level: 'A1', theme: 'Vocabulary', front: 'Quais são as cores "White" e "Brown"?', back: 'Branco e Castanho (Marrom).\n\nDica de Prática: "My dog is white and brown".' },
  { id: 'f220', level: 'A1', theme: 'Grammar', front: 'O que significa o verbo modal "Can"?', back: 'Poder / Conseguir / Ter a habilidade de.\n\nDica de Prática: "I can speak English, but I cannot (can\'t) speak French".' },

  // ==========================================
  // NÍVEL A2 (221 - 240)
  // ==========================================
  { id: 'f221', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Take" (Levar/Tomar)?', back: 'Took.\n\nDica de Prática: "I took a taxi to the airport yesterday".' },
  { id: 'f222', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Buy" (Comprar)?', back: 'Bought.\n\nDica de Prática: "She bought a new phone last week".' },
  { id: 'f223', level: 'A2', theme: 'Grammar', front: 'Como se diz "Mais fácil que" (Comparativo de Easy)?', back: 'Easier than.\n\nDica de Prática: "English is easier than Chinese". (O "y" muda para "ier").' },
  { id: 'f224', level: 'A2', theme: 'Vocabulary', front: 'Qual é a diferença entre "Teach" e "Learn"?', back: 'Teach = Ensinar. Learn = Aprender.\n\nDica de Prática: "The teacher teaches, the student learns".' },
  { id: 'f225', level: 'A2', theme: 'Phrasal Verbs', front: 'O que significa "Try on"?', back: 'Experimentar (uma peça de roupa).\n\nDica de Prática: "Can I try on this shirt before buying it?".' },
  { id: 'f226', level: 'A2', theme: 'Prepositions', front: 'Como dizer os períodos do dia: Manhã, Tarde e Noite?', back: 'IN the morning, IN the afternoon, AT night.\n\nDica de Prática: (Atenção à exceção do "at night").' },
  { id: 'f227', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Travel" e "Trip"?', back: 'Travel = Verbo (Viajar) ou substantivo geral. Trip = A viagem em si (A trip to Paris).\n\nDica de Prática: "I love to travel. My last trip was great".' },
  { id: 'f228', level: 'A2', theme: 'Grammar', front: 'Como expressar uma obrigação do dia a dia?', back: 'Have to.\n\nDica de Prática: "I have to wake up at 6 AM every day".' },
  { id: 'f229', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Tosse" e "Febre"?', back: 'Cough / Fever.\n\nDica de Prática: "I can\'t go to school, I have a cough and a fever".' },
  { id: 'f230', level: 'A2', theme: 'Grammar', front: 'Quando usamos "Something" e "Anything"?', back: 'Something = Afirmativas (Algo). Anything = Negativas/Perguntas (Nada/Alguma coisa).\n\nDica de Prática: "I need something to eat. Do you have anything?".' },
  { id: 'f231', level: 'A2', theme: 'Vocabulary', front: 'O que significam os hobbies "Fishing" e "Hiking"?', back: 'Pescar / Fazer caminhadas na natureza.\n\nDica de Prática: "We are going hiking in the mountains this weekend".' },
  { id: 'f232', level: 'A2', theme: 'Vocabulary', front: 'Qual é a diferença entre "Tired" e "Tiring"?', back: 'Tired = Cansado (pessoa). Tiring = Cansativo (a coisa/atividade).\n\nDica de Prática: "The game was tiring, so the players are tired".' },
  { id: 'f233', level: 'A2', theme: 'Vocabulary', front: 'Como dar direções: "Passar por" e "Atravessar"?', back: 'Go past / Cross.\n\nDica de Prática: "Go past the bank and cross the street".' },
  { id: 'f234', level: 'A2', theme: 'Collocations', front: 'Como dizer "Lavar a loiça" e "Fazer a cama"?', back: 'Do the dishes / Make the bed.\n\nDica de Prática: "I make the bed every morning and do the dishes at night".' },
  { id: 'f235', level: 'A2', theme: 'Grammar', front: 'Para que serve a palavra "While" no passado?', back: 'Significa "Enquanto" e liga ações contínuas.\n\nDica de Prática: "I was reading while he was sleeping".' },
  { id: 'f236', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Boss" e "Employee"?', back: 'Chefe / Funcionário (Empregado).\n\nDica de Prática: "The boss gave a bonus to the employee".' },
  { id: 'f237', level: 'A2', theme: 'Phrasal Verbs', front: 'Como dizer "Entrar" e "Sair" de transportes públicos (autocarro, comboio)?', back: 'Get on / Get off.\n\nDica de Prática: "Get on the bus now, we need to get off at the next stop".' },
  { id: 'f238', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Foggy" e "Cloudy"?', back: 'Com nevoeiro (neblina) / Nublado.\n\nDica de Prática: "Drive slowly, it is very foggy today".' },
  { id: 'f239', level: 'A2', theme: 'Grammar', front: 'Como se faz o plural de "Man" e "Woman"?', back: 'Men / Women (plural irregular).\n\nDica de Prática: "Two men and three women are in the room".' },
  { id: 'f240', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Ponte" e "Rio"?', back: 'Bridge / River.\n\nDica de Prática: "We walked across the bridge over the river".' },

  // ==========================================
  // NÍVEL B1 (241 - 260)
  // ==========================================
  { id: 'f241', level: 'B1', theme: 'Grammar', front: 'Quando usamos "Ever" no Present Perfect?', back: 'Para perguntar sobre experiências de vida ("Alguma vez?").\n\nDica de Prática: "Have you ever been to Japan?" (Alguma vez estiveste no Japão?).' },
  { id: 'f242', level: 'B1', theme: 'Grammar', front: 'Diferença entre Present Perfect e Past Simple?', back: 'Past Simple: Tempo definido (Yesterday). Present Perfect: Tempo indefinido na vida ou com ligação ao presente.\n\nDica de Prática: "I saw him yesterday" vs "I have seen him before".' },
  { id: 'f243', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Run out of"?', back: 'Ficar sem algo / Esgotar.\n\nDica de Prática: "We have run out of coffee. I need to buy more".' },
  { id: 'f244', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Work out"?', back: 'Fazer exercício físico ou resolver-se (um problema).\n\nDica de Prática: "I work out at the gym" / "Don\'t worry, everything will work out".' },
  { id: 'f245', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Find out"?', back: 'Descobrir (informação).\n\nDica de Prática: "I need to find out what time the train leaves".' },
  { id: 'f246', level: 'B1', theme: 'Grammar', front: 'Como se forma a Voz Passiva no Passado?', back: 'Was/Were + Particípio Passado.\n\nDica de Prática: "The house was built in 1990" (A casa foi construída em 1990).' },
  { id: 'f247', level: 'B1', theme: 'Grammar', front: 'Para que servem "Where" e "When" como pronomes relativos?', back: 'Where = Onde (Lugar). When = Quando (Tempo).\n\nDica de Prática: "This is the city where I was born".' },
  { id: 'f248', level: 'B1', theme: 'Collocations', front: 'Diz-se "Do an effort" ou "Make an effort"?', back: 'Make an effort (Fazer um esforço).\n\nDica de Prática: "You must make an effort if you want to learn English".' },
  { id: 'f249', level: 'B1', theme: 'Vocabulary', front: 'O que significa a expressão "Take place"?', back: 'Ocorrer / Acontecer (normalmente eventos planeados).\n\nDica de Prática: "The meeting will take place in room 4".' },
  { id: 'f250', level: 'B1', theme: 'Vocabulary', front: 'O que significa o verbo "Commute"?', back: 'A viagem diária de casa para o trabalho/escola.\n\nDica de Prática: "I commute by train every morning".' },
  { id: 'f251', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Postpone"?', back: 'Adiar (sinónimo formal de "put off").\n\nDica de Prática: "The match was postponed because of the rain".' },
  { id: 'f252', level: 'B1', theme: 'Idioms', front: 'O que significa a expressão "Break a leg"?', back: 'Boa sorte! (Usado muito em contextos de apresentações/teatro).\n\nDica de Prática: "You have a test today? Break a leg!".' },
  { id: 'f253', level: 'B1', theme: 'Idioms', front: 'O que significa "Call it a day"?', back: 'Dar o dia por terminado (parar de trabalhar).\n\nDica de Prática: "We have worked for 10 hours. Let\'s call it a day".' },
  { id: 'f254', level: 'B1', theme: 'Grammar', front: 'Qual é a diferença entre "Used to" e "Be used to"?', back: 'Used to = Costumava (hábito passado). Be used to = Estar habituado a (presente).\n\nDica de Prática: "I used to wake up late, but now I am used to waking up early".' },
  { id: 'f255', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Disappointed"?', back: 'Desiludido / Dececionado.\n\nDica de Prática: "I was disappointed with the movie end".' },
  { id: 'f256', level: 'B1', theme: 'Grammar', front: 'O que significam "However" e "Therefore"?', back: 'However = No entanto (contraste). Therefore = Portanto (conclusão).\n\nDica de Prática: "It was cold. However, we went out. Therefore, we got sick".' },
  { id: 'f257', level: 'B1', theme: 'Grammar', front: 'Como se formam as "Question Tags" (ex: "Não é?")', back: 'Verbo auxiliar oposto ao da frase principal.\n\nDica de Prática: "You like pizza, DON\'T YOU?" / "He is nice, ISN\'T HE?".' },
  { id: 'f258', level: 'B1', theme: 'Vocabulary', front: 'Falso amigo: "Sensible" vs "Sensitive"?', back: 'Sensible = Sensato/Racional. Sensitive = Sensível.\n\nDica de Prática: "It was a sensible decision. Don\'t cry, you are too sensitive".' },
  { id: 'f259', level: 'B1', theme: 'Vocabulary', front: 'Falso amigo: O que significa "Sympathetic"?', back: 'Compreensivo/Solidário com a dor do outro (NÃO é "simpático").\n\nDica de Prática: "She was very sympathetic when my dog died". (Simpático = Nice/Friendly).' },
  { id: 'f260', level: 'B1', theme: 'Phrasal Verbs', front: 'Qual é a regra gramatical após "Look forward to"?', back: 'O verbo seguinte tem de levar "-ing".\n\nDica de Prática: "I look forward TO SEEING you" (e não "to see").' },

  // ==========================================
  // NÍVEL B2 (261 - 280)
  // ==========================================
  { id: 'f261', level: 'B2', theme: 'Grammar', front: 'Como usar a estrutura causativa "Have something done"?', back: 'Sujeito + Have/Get + Objeto + Particípio Passado (indica que contratou alguém para fazer).\n\nDica de Prática: "I had my car repaired" (O mecânico arranjou o meu carro).' },
  { id: 'f262', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Put up with"?', back: 'Tolerar ou aguentar algo desagradável.\n\nDica de Prática: "I don\'t know how you put up with that terrible noise".' },
  { id: 'f263', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Turn out"?', back: 'Resultar, acabar por ser, ou acontecer de certa forma.\n\nDica de Prática: "The party turned out to be a huge success".' },
  { id: 'f264', level: 'B2', theme: 'Collocations', front: 'O que significa "Strictly forbidden"?', back: 'Terminantemente proibido.\n\nDica de Prática: "Smoking is strictly forbidden on this flight".' },
  { id: 'f265', level: 'B2', theme: 'Collocations', front: 'O que significa "Highly recommended"?', back: 'Altamente recomendado.\n\nDica de Prática: "This restaurant is highly recommended by locals".' },
  { id: 'f266', level: 'B2', theme: 'Idioms', front: 'O que significa "Hit the nail on the head"?', back: 'Acertar na mouche, dizer exatamente a coisa certa.\n\nDica de Prática: "You hit the nail on the head when you mentioned the budget issue".' },
  { id: 'f267', level: 'B2', theme: 'Idioms', front: 'O que significa "Let the cat out of the bag"?', back: 'Revelar um segredo acidentalmente.\n\nDica de Prática: "It was supposed to be a surprise party, but John let the cat out of the bag".' },
  { id: 'f268', level: 'B2', theme: 'Vocabulary', front: 'Qual é a diferença entre "Overrate" e "Underrate"?', back: 'Overrate = Sobrevalorizar (dar muito valor). Underrate = Subestimar.\n\nDica de Prática: "I think that movie is completely overrated".' },
  { id: 'f269', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Flawless"?', back: 'Sem falhas, perfeito.\n\nDica de Prática: "Her performance on the piano was absolute flawless".' },
  { id: 'f270', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Overwhelmed"?', back: 'Sobrecarregado (emocionalmente ou por tarefas).\n\nDica de Prática: "I am feeling overwhelmed with so much work to do".' },
  { id: 'f271', level: 'B2', theme: 'Grammar', front: 'Qual a diferença gramatical entre "Despite" e "In spite of"?', back: 'Nenhuma no significado, mas "Despite" NUNCA leva "of".\n\nDica de Prática: "Despite the rain..." ou "In spite of the rain...".' },
  { id: 'f272', level: 'B2', theme: 'Grammar', front: 'Que tempo verbal se usa após "By the time" (no passado)?', back: 'Past Perfect (para a ação que já tinha ocorrido).\n\nDica de Prática: "By the time we arrived, the movie had already started".' },
  { id: 'f273', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Broaden your horizons"?', back: 'Expandir os horizontes (ganhar novas experiências e conhecimentos).\n\nDica de Prática: "Traveling to Asia really broadened my horizons".' },
  { id: 'f274', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Brush up on"?', back: 'Rever ou praticar algo que já se aprendeu para não esquecer.\n\nDica de Prática: "I need to brush up on my Spanish before going to Madrid".' },
  { id: 'f275', level: 'B2', theme: 'Vocabulary', front: 'O que significa "To take for granted"?', back: 'Não dar o devido valor (assumir que algo estará sempre lá).\n\nDica de Prática: "We often take clean water for granted".' },
  { id: 'f276', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Complacent"?', back: 'Acomodado, demasiado satisfeito consigo próprio ao ponto de não se esforçar mais.\n\nDica de Prática: "We cannot afford to become complacent in this market".' },
  { id: 'f277', level: 'B2', theme: 'Vocabulary', front: 'O que significa o verbo "Entail"?', back: 'Implicar, envolver como consequência necessária.\n\nDica de Prática: "This new role will entail a lot of traveling".' },
  { id: 'f278', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Come across"?', back: 'Encontrar por acaso (pessoas ou coisas).\n\nDica de Prática: "I came across some old photos while cleaning the attic".' },
  { id: 'f279', level: 'B2', theme: 'Grammar', front: 'Como usar "Would rather"?', back: 'Significa "Preferia". É seguido pelo verbo na forma base (sem "to").\n\nDica de Prática: "I would rather stay home tonight".' },
  { id: 'f280', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Reckless"?', back: 'Imprudente, irresponsável (não pensar nos riscos).\n\nDica de Prática: "He was arrested for reckless driving".' },

  // ==========================================
  // NÍVEL C1 (281 - 300)
  // ==========================================
  { id: 'f281', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Mundane"?', back: 'Mundano, banal, sem interesse ou aborrecido no dia a dia.\n\nDica de Prática: "She hates doing mundane chores like ironing".' },
  { id: 'f282', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Tenacious"?', back: 'Tenaz, persistente, que não desiste facilmente.\n\nDica de Prática: "He was tenacious in his pursuit of justice".' },
  { id: 'f283', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Pragmatic"?', back: 'Pragmático, que lida com as coisas de forma sensata e realista.\n\nDica de Prática: "We need a pragmatic approach to solve this crisis".' },
  { id: 'f284', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ambiguous"?', back: 'Ambíguo, que tem mais do que um significado possível (não é claro).\n\nDica de Prática: "The instructions were so ambiguous that nobody understood them".' },
  { id: 'f285', level: 'C1', theme: 'Idioms', front: 'O que significa "The best of both worlds"?', back: 'O melhor de dois mundos (juntar os benefícios de duas coisas diferentes).\n\nDica de Prática: "Working from home offers the best of both worlds".' },
  { id: 'f286', level: 'C1', theme: 'Idioms', front: 'O que significa "To be on the fence"?', back: 'Estar indeciso, não tomar partido num assunto.\n\nDica de Prática: "I\'m still on the fence about whether to buy the house or not".' },
  { id: 'f287', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Factor in"?', back: 'Ter algo em consideração ao fazer um cálculo ou plano.\n\nDica de Prática: "You need to factor in the cost of transport when booking the hotel".' },
  { id: 'f288', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Gloss over"?', back: 'Passar por alto, ignorar ou evitar falar sobre um problema seriamente.\n\nDica de Prática: "The politician tried to gloss over the economic crisis".' },
  { id: 'f289', level: 'C1', theme: 'Grammar', front: 'Como se usa a inversão com "Little"?', back: 'Para dar efeito dramático, inverte-se verbo/sujeito: Little did I know = Mal sabia eu.\n\nDica de Prática: "Little did she know that it was a trap".' },
  { id: 'f290', level: 'C1', theme: 'Grammar', front: 'O que é uma "Participle Clause" com particípio passado?', back: 'Substitui uma oração passiva para ser mais concisa.\n\nDica de Prática: "Seen from this angle, the building looks taller" (= If it is seen...).' },
  { id: 'f291', level: 'C1', theme: 'Collocations', front: 'O que significa "Blatant disregard"?', back: 'Desrespeito descarado / Ignorar regras de forma óbvia.\n\nDica de Prática: "He parked there with blatant disregard for the rules".' },
  { id: 'f292', level: 'C1', theme: 'Collocations', front: 'O que significa "Detrimental effect"?', back: 'Efeito prejudicial ou nocivo.\n\nDica de Prática: "Stress can have a detrimental effect on your health".' },
  { id: 'f293', level: 'C1', theme: 'Vocabulary', front: 'O que significa o verbo "Alleviate"?', back: 'Aliviar, atenuar (a dor, o sofrimento, o stress).\n\nDica de Prática: "This medicine will help to alleviate the symptoms".' },
  { id: 'f294', level: 'C1', theme: 'Vocabulary', front: 'O que significa o verbo "Hinder"?', back: 'Dificultar, atrasar ou impedir o progresso de algo.\n\nDica de Prática: "The heavy rain hindered our progress".' },
  { id: 'f295', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Resilient"?', back: 'Resiliente, capaz de recuperar rapidamente de dificuldades.\n\nDica de Prática: "Children are incredibly resilient".' },
  { id: 'f296', level: 'C1', theme: 'Idioms', front: 'O que significa "Read between the lines"?', back: 'Ler nas entrelinhas (perceber o verdadeiro significado escondido).\n\nDica de Prática: "He said he was fine, but reading between the lines, I knew he was angry".' },
  { id: 'f297', level: 'C1', theme: 'Collocations', front: 'O que significa "A sweeping generalization"?', back: 'Uma generalização excessiva (aplicar uma regra a tudo sem considerar exceções).\n\nDica de Prática: "Saying all teenagers are lazy is a sweeping generalization".' },
  { id: 'f298', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Redundant" no contexto de trabalho?', back: 'Ser despedido porque a função já não é necessária (Lay off).\n\nDica de Prática: "Many factory workers were made redundant last year".' },
  { id: 'f299', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Single out"?', back: 'Selecionar ou destacar uma pessoa/coisa de um grupo (geralmente para criticar ou elogiar).\n\nDica de Prática: "Why did the teacher single him out for punishment?".' },
  { id: 'f300', level: 'C1', theme: 'Grammar', front: 'Como se usa o Subjuntivo após a expressão "It is imperative that..."?', back: 'O verbo da frase seguinte deve estar na sua forma base (infinitivo sem "to").\n\nDica de Prática: "It is imperative that he BE at the meeting on time" (Não "is").' },
  // ==========================================
  // NÍVEL A1 (301 - 320)
  // ==========================================
  { id: 'f301', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Primo" e "Sobrinho"?', back: 'Cousin / Nephew.\n\nDica de Prática: "My cousin and my nephew are playing in the garden".' },
  { id: 'f302', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Vaca" e "Ovelha"?', back: 'Cow / Sheep.\n\nDica de Prática: "The cow gives milk and the sheep gives wool". (Nota: O plural de sheep é igual: one sheep, two sheep).' },
  { id: 'f303', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Frango" e "Carne de vaca"?', back: 'Chicken / Beef.\n\nDica de Prática: "I would like chicken and rice, please".' },
  { id: 'f304', level: 'A1', theme: 'Grammar', front: 'Quais são os possessivos para "Eu", "Tu", "Ele" e "Ela"?', back: 'My, Your, His, Her.\n\nDica de Prática: "My name is John and her name is Mary".' },
  { id: 'f305', level: 'A1', theme: 'Grammar', front: 'Qual é o plural de "Person" (Pessoa)?', back: 'People (Pessoas).\n\nDica de Prática: "There are three people in the car".' },
  { id: 'f306', level: 'A1', theme: 'Vocabulary', front: 'Como dizer "Ontem", "Hoje" e "Amanhã"?', back: 'Yesterday, Today, Tomorrow.\n\nDica de Prática: "Yesterday was Sunday, today is Monday".' },
  { id: 'f307', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Esquerda" e "Direita"?', back: 'Left / Right.\n\nDica de Prática: "Turn left at the hospital, then turn right".' },
  { id: 'f308', level: 'A1', theme: 'Vocabulary', front: 'Qual a diferença entre "Want" e "Need"?', back: 'Want = Querer (desejo). Need = Precisar (necessidade).\n\nDica de Prática: "I want a new car, but I need water to live".' },
  { id: 'f309', level: 'A1', theme: 'Vocabulary', front: 'O que significam "Like" e "Love"?', back: 'Gostar / Amar (ou adorar).\n\nDica de Prática: "I like apples, but I love chocolate".' },
  { id: 'f310', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Telemóvel" e "Computador"?', back: 'Phone (ou Mobile/Cell phone) / Computer.\n\nDica de Prática: "I read emails on my phone and work on my computer".' },
  { id: 'f311', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Restaurant" e "Supermarket"?', back: 'Restaurante / Supermercado.\n\nDica de Prática: "We buy food at the supermarket and eat at the restaurant".' },
  { id: 'f312', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Chapéu" e "Casaco"?', back: 'Hat / Coat (ou Jacket).\n\nDica de Prática: "It is cold, put on your coat and your hat".' },
  { id: 'f313', level: 'A1', theme: 'Prepositions', front: 'Como dizer que algo está "Em frente a" e "Atrás de"?', back: 'In front of / Behind.\n\nDica de Prática: "The car is in front of the house. The garden is behind it".' },
  { id: 'f314', level: 'A1', theme: 'Grammar', front: 'Como se diz a idade em inglês (ex: Tenho 25 anos)?', back: 'Usa-se o verbo To Be: "I am 25 years old".\n\nDica de Prática: NUNCA use o verbo ter (I have 25) para idades!' },
  { id: 'f315', level: 'A1', theme: 'Vocabulary', front: 'Quais são as cores "Orange" e "Purple"?', back: 'Cor-de-laranja e Roxo.\n\nDica de Prática: "She is wearing a purple dress".' },
  { id: 'f316', level: 'A1', theme: 'Vocabulary', front: 'Qual é o oposto de "Fast" (Rápido)?', back: 'Slow (Lento).\n\nDica de Prática: "The train is fast, but the bus is slow".' },
  { id: 'f317', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Jovem" e "Velho"?', back: 'Young / Old.\n\nDica de Prática: "My grandfather is old, but my brother is young".' },
  { id: 'f318', level: 'A1', theme: 'Vocabulary', front: 'O que significam os verbos "Open" e "Close"?', back: 'Abrir / Fechar.\n\nDica de Prática: "Please, open the window and close the door".' },
  { id: 'f319', level: 'A1', theme: 'Phrases', front: 'Quando usar "Excuse me" vs "I am sorry"?', back: 'Excuse me = Com licença (para pedir atenção ou passagem). I am sorry = Desculpa (para pedir perdão).\n\nDica de Prática: "Excuse me, where is the station?" / "I am sorry I am late".' },
  { id: 'f320', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Rua" e "Cidade"?', back: 'Street / City.\n\nDica de Prática: "I live on Main Street in a big city".' },

  // ==========================================
  // NÍVEL A2 (321 - 340)
  // ==========================================
  { id: 'f321', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Drink" (Beber) e "Drive" (Conduzir)?', back: 'Drank / Drove.\n\nDica de Prática: "I drank water and he drove the car".' },
  { id: 'f322', level: 'A2', theme: 'Grammar', front: 'Como se diz "Pior que" (Comparativo de Bad)?', back: 'Worse than.\n\nDica de Prática: "The movie was worse than the book".' },
  { id: 'f323', level: 'A2', theme: 'Grammar', front: 'Como se diz "O mais bonito" (Superlativo)?', back: 'The most beautiful.\n\nDica de Prática: Adjetivos longos usam "the most". Ex: "She is the most beautiful girl".' },
  { id: 'f324', level: 'A2', theme: 'Grammar', front: 'Para que serve o verbo modal "Should"?', back: 'Para dar conselhos (Devias / Deveria).\n\nDica de Prática: "You look tired, you should sleep".' },
  { id: 'f325', level: 'A2', theme: 'Grammar', front: 'Para que serve "Mustn\'t"?', back: 'Indica uma proibição estrita (Não deves / É proibido).\n\nDica de Prática: "You mustn\'t smoke in the hospital".' },
  { id: 'f326', level: 'A2', theme: 'Phrasal Verbs', front: 'Diferença entre "Wake up" e "Get up"?', back: 'Wake up = Acordar (abrir os olhos). Get up = Levantar da cama.\n\nDica de Prática: "I wake up at 7, but I get up at 7:30".' },
  { id: 'f327', level: 'A2', theme: 'Phrasal Verbs', front: 'Como dizer "Vestir/Calçar" e "Despir/Descalçar"?', back: 'Put on / Take off.\n\nDica de Prática: "Put on your shoes and take off your hat".' },
  { id: 'f328', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Ticket" e "Passport"?', back: 'Bilhete (Passagem) / Passaporte.\n\nDica de Prática: "Show your passport and flight ticket, please".' },
  { id: 'f329', level: 'A2', theme: 'Vocabulary', front: 'O que significam "Delay" e "Cancel"?', back: 'Atrasar / Cancelar.\n\nDica de Prática: "My flight is delayed by one hour".' },
  { id: 'f330', level: 'A2', theme: 'Grammar', front: 'Para que serve o Present Continuous (I am working)?', back: 'Para ações que estão a acontecer neste exato momento.\n\nDica de Prática: "I can\'t talk right now, I am working".' },
  { id: 'f331', level: 'A2', theme: 'Grammar', front: 'Como usar "Will" para decisões espontâneas?', back: 'Usa-se quando decidimos fazer algo no momento em que falamos.\n\nDica de Prática: "The phone is ringing! - I will answer it".' },
  { id: 'f332', level: 'A2', theme: 'Grammar', front: 'Como oferecer algo educadamente? (Gostarias de...?)', back: 'Would you like...?\n\nDica de Prática: "Would you like a cup of tea?".' },
  { id: 'f333', level: 'A2', theme: 'Vocabulary', front: 'O que significam os advérbios "Often" e "Rarely"?', back: 'Frequentemente / Raramente.\n\nDica de Prática: "I often go to the gym, but I rarely run".' },
  { id: 'f334', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Hungry" e "Thirsty"?', back: 'Com fome / Com sede.\n\nDica de Prática: "I am hungry, let\'s eat a pizza. I am thirsty, I need water".' },
  { id: 'f335', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Excited" e "Exciting"?', back: 'Excited = Entusiasmado (pessoa). Exciting = Emocionante (coisa/situação).\n\nDica de Prática: "The game is exciting, so I am excited".' },
  { id: 'f336', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Borrow" e "Lend"?', back: 'Borrow = Pedir emprestado. Lend = Emprestar a alguém.\n\nDica de Prática: "Can I borrow your pen?" / "I will lend you my pen".' },
  { id: 'f337', level: 'A2', theme: 'Prepositions', front: 'Como dizer "De autocarro" e "A pé"?', back: 'By bus / On foot.\n\nDica de Prática: "I go to work by bus, but I go to the park on foot".' },
  { id: 'f338', level: 'A2', theme: 'Prepositions', front: 'Quais as preposições para Anos, Dias e Horas?', back: 'IN (Anos), ON (Dias), AT (Horas).\n\nDica de Prática: "In 2026, On Monday, At 8 PM".' },
  { id: 'f339', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Braço", "Perna" e "Costas"?', back: 'Arm / Leg / Back.\n\nDica de Prática: "My back hurts after carrying that heavy box".' },
  { id: 'f340', level: 'A2', theme: 'Vocabulary', front: 'O que é um "Customer" e um "Shop assistant"?', back: 'Cliente / Lojista (Empregado de loja).\n\nDica de Prática: "The shop assistant helped the customer find the shoes".' },

  // ==========================================
  // NÍVEL B1 (341 - 360)
  // ==========================================
  { id: 'f341', level: 'B1', theme: 'Grammar', front: 'Para que usamos "Have you ever...?"', back: 'Para perguntar sobre experiências de vida até ao momento presente.\n\nDica de Prática: "Have you ever eaten sushi?" (Alguma vez comeste sushi?).' },
  { id: 'f342', level: 'B1', theme: 'Grammar', front: 'Qual a diferença entre "For" e "Since" no Present Perfect?', back: 'For = Duração (For 3 years). Since = Ponto de início (Since 2023).\n\nDica de Prática: "I have worked here for 5 months, since January".' },
  { id: 'f343', level: 'B1', theme: 'Grammar', front: 'Qual é o uso clássico do Past Continuous com o Past Simple?', back: 'Uma ação longa (Continuous) que é interrompida por uma ação curta (Simple).\n\nDica de Prática: "I was watching TV when the phone rang".' },
  { id: 'f344', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Look up"?', back: 'Pesquisar uma informação (num dicionário, lista ou internet).\n\nDica de Prática: "If you don\'t know the word, look it up in the dictionary".' },
  { id: 'f345', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Give up"?', back: 'Desistir ou abandonar um hábito.\n\nDica de Prática: "Never give up on your dreams!" / "I gave up smoking".' },
  { id: 'f346', level: 'B1', theme: 'Grammar', front: 'Como se usa "Used to"?', back: 'Para hábitos ou estados no passado que já não são verdade no presente.\n\nDica de Prática: "I used to play the piano when I was a kid".' },
  { id: 'f347', level: 'B1', theme: 'Grammar', front: 'Qual é a função de "May" e "Might"?', back: 'Expressar probabilidade ou possibilidade (talvez).\n\nDica de Prática: "Take your umbrella, it might rain later".' },
  { id: 'f348', level: 'B1', theme: 'Grammar', front: 'Diferença entre os pronomes relativos "Who" e "Which"?', back: 'Who = Para pessoas. Which = Para coisas ou animais.\n\nDica de Prática: "The man WHO lives here has a car WHICH is very fast".' },
  { id: 'f349', level: 'B1', theme: 'Collocations', front: 'Diz-se "Do a decision" ou "Make a decision"?', back: 'Make a decision (Tomar uma decisão).\n\nDica de Prática: "It\'s hard, but you have to make a decision today".' },
  { id: 'f350', level: 'B1', theme: 'Collocations', front: 'Diz-se "Make a favor" ou "Do a favor"?', back: 'Do a favor (Fazer um favor).\n\nDica de Prática: "Could you do me a favor and open the door?".' },
  { id: 'f351', level: 'B1', theme: 'Vocabulary', front: 'Qual a diferença entre "Employer" e "Employee"?', back: 'Employer = Empregador/Patrão. Employee = Funcionário/Empregado.\n\nDica de Prática: "The employer pays the employees at the end of the month".' },
  { id: 'f352', level: 'B1', theme: 'Vocabulary', front: 'Falso cognato: O que significa "Actually"?', back: 'Na verdade / O facto é que. (NÃO significa "Atualmente").\n\nDica de Prática: "People think I\'m Spanish, but actually I\'m Portuguese".' },
  { id: 'f353', level: 'B1', theme: 'Vocabulary', front: 'Falso cognato: O que significa "Pretend"?', back: 'Fingir. (NÃO significa "Pretender/Querer").\n\nDica de Prática: "He closed his eyes to pretend he was sleeping".' },
  { id: 'f354', level: 'B1', theme: 'Grammar', front: 'Como se constrói a Voz Passiva no Presente (Passive Voice)?', back: 'Am/Is/Are + Particípio Passado.\n\nDica de Prática: "This car IS MADE in Japan" (Este carro é feito no Japão).' },
  { id: 'f355', level: 'B1', theme: 'Grammar', front: 'Como se constrói a Voz Passiva no Passado (Passive Voice)?', back: 'Was/Were + Particípio Passado.\n\nDica de Prática: "The Eiffel Tower WAS BUILT in 1889".' },
  { id: 'f356', level: 'B1', theme: 'Grammar', front: 'Como se forma a 1ª Condicional (First Conditional)?', back: 'If + Present Simple, ... will + verbo.\n\nDica de Prática: "If it rains, I will stay at home" (Condição real e possível).' },
  { id: 'f357', level: 'B1', theme: 'Vocabulary', front: 'Falso cognato: Diferença entre "Sensible" e "Sensitive"?', back: 'Sensible = Sensato/Racional. Sensitive = Sensível (emocional ou físico).\n\nDica de Prática: "It was a sensible decision. Don\'t cry, you are too sensitive".' },
  { id: 'f358', level: 'B1', theme: 'Idioms', front: 'O que significa a expressão "A piece of cake"?', back: 'Algo muito fácil.\n\nDica de Prática: "Don\'t worry about the exam, it will be a piece of cake".' },
  { id: 'f359', level: 'B1', theme: 'Idioms', front: 'O que significa estar "Under the weather"?', back: 'Sentir-se doente ou indisposto.\n\nDica de Prática: "I\'m not going to work, I\'m feeling a bit under the weather".' },
  { id: 'f360', level: 'B1', theme: 'Grammar', front: 'Como transformar adjetivos em advérbios de modo (ex: quick, careful)?', back: 'Normalmente adiciona-se "-ly" (Quickly, Carefully).\n\nDica de Prática: "He drives very carefully".' },

  // ==========================================
  // NÍVEL B2 (361 - 380)
  // ==========================================
  { id: 'f361', level: 'B2', theme: 'Grammar', front: 'Como se forma a 2ª Condicional (Second Conditional)?', back: 'If + Past Simple, ... would + verbo.\n\nDica de Prática: "If I won the lottery, I would buy a house" (Situação hipotética no presente).' },
  { id: 'f362', level: 'B2', theme: 'Grammar', front: 'Como se forma a 3ª Condicional (Third Conditional)?', back: 'If + Past Perfect, ... would have + particípio passado.\n\nDica de Prática: "If I had known, I would have helped you" (Impossível de mudar agora).' },
  { id: 'f363', level: 'B2', theme: 'Grammar', front: 'O que significa a estrutura "Have something done"?', back: 'Que pagámos ou pedimos a alguém para fazer um serviço por nós.\n\nDica de Prática: "I had my car washed yesterday" (Alguém lavou o meu carro).' },
  { id: 'f364', level: 'B2', theme: 'Phrasal Verbs', front: 'Qual é a regra gramatical essencial após "Look forward to"?', back: 'O verbo a seguir tem de estar no gerúndio (-ing).\n\nDica de Prática: "I look forward to HEARING from you" (e não to hear).' },
  { id: 'f365', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Run out of"?', back: 'Ficar sem algo (esgotar).\n\nDica de Prática: "We have run out of milk, can you buy some?".' },
  { id: 'f366', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Put up with"?', back: 'Tolerar, suportar algo ou alguém irritante.\n\nDica de Prática: "I can\'t put up with this noise anymore!".' },
  { id: 'f367', level: 'B2', theme: 'Idioms', front: 'O que significa "Break the ice"?', back: 'Quebrar o gelo (aliviar a tensão inicial numa interação social).\n\nDica de Prática: "He told a joke to break the ice at the meeting".' },
  { id: 'f368', level: 'B2', theme: 'Idioms', front: 'O que significa "Spill the beans"?', back: 'Dar com a língua nos dentes / Revelar um segredo.\n\nDica de Prática: "Come on, spill the beans! What did she say?".' },
  { id: 'f369', level: 'B2', theme: 'Grammar', front: 'Como usar "Wish" para desejar que algo AGORA fosse diferente?', back: 'Wish + Past Simple.\n\nDica de Prática: "I wish I had more money" (Quem me dera ter mais dinheiro agora).' },
  { id: 'f370', level: 'B2', theme: 'Grammar', front: 'Como usar "Wish" para demonstrar arrependimento no PASSADO?', back: 'Wish + Past Perfect.\n\nDica de Prática: "I wish I had studied harder for the exam" (Arrependo-me de não ter estudado).' },
  { id: 'f371', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Overwhelmed"?', back: 'Sobrecarregado (seja por emoções, tarefas ou volume de trabalho).\n\nDica de Prática: "I am feeling overwhelmed with all these new projects".' },
  { id: 'f372', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Reliable"?', back: 'Fiável, de confiança (em quem se pode confiar).\n\nDica de Prática: "He is a very reliable employee".' },
  { id: 'f373', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Stubborn"?', back: 'Teimoso.\n\nDica de Prática: "She is too stubborn to admit she was wrong".' },
  { id: 'f374', level: 'B2', theme: 'Grammar', front: 'Qual é a regra de ouro para usar "Despite" ou "In spite of"?', back: 'Ambos significam "Apesar de", mas "Despite" NUNCA leva "of". Seguem-se de substantivo ou verbo em -ing.\n\nDica de Prática: "Despite the rain, we played football".' },
  { id: 'f375', level: 'B2', theme: 'Grammar', front: 'O que significa a palavra "Unless"?', back: 'A não ser que / A menos que (If not).\n\nDica de Prática: "I won\'t go to the party unless you come with me".' },
  { id: 'f376', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Flawless"?', back: 'Sem falhas, absolutamente perfeito.\n\nDica de Prática: "Her English pronunciation is flawless".' },
  { id: 'f377', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Breathtaking"?', back: 'Deslumbrante, de cortar a respiração.\n\nDica de Prática: "The view from the mountain was breathtaking".' },
  { id: 'f378', level: 'B2', theme: 'Collocations', front: 'O que significa "Bear in mind"?', back: 'Ter em mente / Ter em consideração.\n\nDica de Prática: "Bear in mind that the deadline is tomorrow".' },
  { id: 'f379', level: 'B2', theme: 'Collocations', front: 'O que significa "Take for granted"?', back: 'Dar algo por garantido (sem dar o devido valor).\n\nDica de Prática: "We often take our health for granted until we get sick".' },
  { id: 'f380', level: 'B2', theme: 'Grammar', front: 'No Reported Speech (Discurso Indireto), o que acontece aos tempos verbais?', back: 'Recuam um tempo no passado (Backshift).\n\nDica de Prática: "I play tennis" -> He said he PLAYED tennis.' },

  // ==========================================
  // NÍVEL C1 (381 - 400)
  // ==========================================
  { id: 'f381', level: 'C1', theme: 'Grammar', front: 'Como se aplica a inversão com "Not only"?', back: 'Inverte-se o verbo auxiliar e o sujeito, tal como numa pergunta.\n\nDica de Prática: "Not only DID HE FAIL the exam, but he also lost his book".' },
  { id: 'f382', level: 'C1', theme: 'Grammar', front: 'Como se usa a estrutura "No sooner... than"?', back: 'Com inversão (Past Perfect) para indicar que uma ação seguiu a outra imediatamente.\n\nDica de Prática: "No sooner HAD I ARRIVED than the meeting started".' },
  { id: 'f383', level: 'C1', theme: 'Grammar', front: 'O que é uma "Cleft Sentence" com "It was..."?', back: 'Estrutura usada para dar foco a uma parte da frase.\n\nDica de Prática: "It was JOHN who sent the email" (Enfatiza que foi o John, não outra pessoa).' },
  { id: 'f384', level: 'C1', theme: 'Grammar', front: 'O que indica uma "Participle Clause" iniciada por "Having + particípio"?', back: 'Substitui orações com "Because" ou "After", indicando que a ação já terminou.\n\nDica de Prática: "Having finished the report, I went home".' },
  { id: 'f385', level: 'C1', theme: 'Idioms', front: 'O que significa "Bite the bullet"?', back: 'Enfrentar uma situação difícil ou dolorosa por ser inevitável.\n\nDica de Prática: "I hate going to the dentist, but I just have to bite the bullet".' },
  { id: 'f386', level: 'C1', theme: 'Idioms', front: 'O que significa "Cut corners"?', back: 'Fazer as coisas à pressa ou de forma barata para poupar tempo/dinheiro (geralmente prejudicando a qualidade).\n\nDica de Prática: "If you cut corners on safety, someone will get hurt".' },
  { id: 'f387', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Boil down to"?', back: 'Resumir-se a (o aspeto mais fundamental de um assunto).\n\nDica de Prática: "The whole problem boils down to a lack of communication".' },
  { id: 'f388', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Rule out"?', back: 'Descartar, excluir uma possibilidade.\n\nDica de Prática: "The police have ruled out murder".' },
  { id: 'f389', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Meticulous"?', back: 'Extremamente detalhista e rigoroso.\n\nDica de Prática: "He is always meticulous in his work".' },
  { id: 'f390', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Pragmatic"?', back: 'Pragmático (lida com as situações de forma prática e não apenas teórica).\n\nDica de Prática: "We need a pragmatic approach to solve this crisis".' },
  { id: 'f391', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ambiguous"?', back: 'Ambíguo, pouco claro, aberto a várias interpretações.\n\nDica de Prática: "The instructions on the manual were highly ambiguous".' },
  { id: 'f392', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Pervasive"?', back: 'Penetrante, generalizado (algo que se espalha e está presente em todo o lado).\n\nDica de Prática: "The pervasive influence of social media is undeniable".' },
  { id: 'f393', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Mitigate"?', back: 'Atenuar, mitigar ou reduzir a severidade de algo.\n\nDica de Prática: "The company took steps to mitigate the environmental impact".' },
  { id: 'f394', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Feasible"?', back: 'Viável, possível de realizar.\n\nDica de Prática: "It\'s a good idea, but is it financially feasible?".' },
  { id: 'f395', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Obsolete"?', back: 'Obsoleto, ultrapassado, que já não se usa.\n\nDica de Prática: "Typewriters have become completely obsolete".' },
  { id: 'f396', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Lucrative"?', back: 'Lucrativo, que dá muito dinheiro.\n\nDica de Prática: "She left teaching to pursue a highly lucrative career in finance".' },
  { id: 'f397', level: 'C1', theme: 'Grammar', front: 'Como se aplica o modo Subjuntivo após a expressão "It is essential that..."?', back: 'Usa-se a forma base do verbo sem o "to" e sem o "s" na terceira pessoa.\n\nDica de Prática: "It is essential that she BE here tomorrow" (e não "is").' },
  { id: 'f398', level: 'C1', theme: 'Collocations', front: 'O que significa "Stark contrast"?', back: 'Um contraste extremo, nítido.\n\nDica de Prática: "His wealth is in stark contrast to the poverty of his neighbors".' },
  { id: 'f399', level: 'C1', theme: 'Collocations', front: 'O que significa "A sweeping generalization"?', back: 'Uma generalização excessiva e perigosa.\n\nDica de Prática: "Saying all politicians are corrupt is a sweeping generalization".' },
  { id: 'f400', level: 'C1', theme: 'Idioms', front: 'O que significa "Play devil\'s advocate"?', back: 'Assumir uma posição contrária num debate só para o estimular ou testar argumentos.\n\nDica de Prática: "I agree with you, I\'m just playing devil\'s advocate".' },
  // ==========================================
  // NÍVEL A1 (401 - 420)
  // ==========================================
  { id: 'f401', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Primavera" e "Verão"?', back: 'Spring / Summer.\n\nDica de Prática: "I love the flowers in spring and the sun in summer".' },
  { id: 'f402', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Outono" e "Inverno"?', back: 'Autumn (ou Fall) / Winter.\n\nDica de Prática: "It snows a lot here in winter".' },
  { id: 'f403', level: 'A1', theme: 'Grammar', front: 'Qual é o plural irregular de "Child" (Criança)?', back: 'Children (Crianças).\n\nDica de Prática: "The children are playing in the park".' },
  { id: 'f404', level: 'A1', theme: 'Grammar', front: 'Qual é o plural irregular de "Tooth" (Dente) e "Foot" (Pé)?', back: 'Teeth (Dentes) / Feet (Pés).\n\nDica de Prática: "Brush your teeth and wash your feet".' },
  { id: 'f405', level: 'A1', theme: 'Vocabulary', front: 'O que significam os verbos "Jump" e "Fly"?', back: 'Saltar / Voar.\n\nDica de Prática: "The boy can jump, but birds can fly".' },
  { id: 'f406', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Near" e "Far"?', back: 'Perto / Longe.\n\nDica de Prática: "My house is near the supermarket, but far from the beach".' },
  { id: 'f407', level: 'A1', theme: 'Vocabulary', front: 'O que significam "Beautiful" e "Ugly"?', back: 'Bonito / Feio.\n\nDica de Prática: "This city is very beautiful".' },
  { id: 'f408', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Fácil" e "Difícil"?', back: 'Easy / Hard (ou Difficult).\n\nDica de Prática: "The test was very hard, not easy".' },
  { id: 'f409', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Sempre" e "Às vezes"?', back: 'Always / Sometimes.\n\nDica de Prática: "I always drink water, but sometimes I drink soda".' },
  { id: 'f410', level: 'A1', theme: 'Grammar', front: 'Como se pergunta "O quê / Qual" e "Quem"?', back: 'What / Who.\n\nDica de Prática: "What is your name? Who is your friend?".' },
  { id: 'f411', level: 'A1', theme: 'Vocabulary', front: 'O que significam "Breakfast", "Lunch" e "Dinner"?', back: 'Pequeno-almoço / Almoço / Jantar.\n\nDica de Prática: "I eat eggs for breakfast".' },
  { id: 'f412', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Cheap" e "Expensive"?', back: 'Barato / Caro.\n\nDica de Prática: "This car is very expensive, I need a cheap one".' },
  { id: 'f413', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Faca", "Garfo" e "Colher"?', back: 'Knife / Fork / Spoon.\n\nDica de Prática: "I need a knife and a fork to eat the meat".' },
  { id: 'f414', level: 'A1', theme: 'Grammar', front: 'Qual é o passado do verbo "To Be" (Ser/Estar)?', back: 'Was (para I/He/She/It) e Were (para You/We/They).\n\nDica de Prática: "I was at home, and they were at school".' },
  { id: 'f415', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Clean" e "Dirty"?', back: 'Limpo / Sujo.\n\nDica de Prática: "Wash your hands, they are dirty".' },
  { id: 'f416', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Muito prazer" (ao conhecer alguém)?', back: 'Nice to meet you.\n\nDica de Prática: "Hello, I am Thiago. Nice to meet you!".' },
  { id: 'f417', level: 'A1', theme: 'Vocabulary', front: 'O que significa "Early" e "Late"?', back: 'Cedo / Tarde (Atrasado).\n\nDica de Prática: "Don\'t be late for the meeting, arrive early".' },
  { id: 'f418', level: 'A1', theme: 'Prepositions', front: 'A preposição correta para fins de semana é "In the weekend" ou "At the weekend"?', back: 'At the weekend (Inglês Britânico) ou On the weekend (Inglês Americano).\n\nDica de Prática: "I play football at the weekend".' },
  { id: 'f419', level: 'A1', theme: 'Grammar', front: 'O que significa a palavra "Because"?', back: 'Porque (usado para dar uma resposta ou razão).\n\nDica de Prática: "Why are you tired? Because I worked a lot".' },
  { id: 'f420', level: 'A1', theme: 'Vocabulary', front: 'Como se diz "Cabelo" e "Rosto"?', back: 'Hair / Face.\n\nDica de Prática: "She has long hair and a beautiful face".' },

  // ==========================================
  // NÍVEL A2 (421 - 440)
  // ==========================================
  { id: 'f421', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Think" (Pensar)?', back: 'Thought.\n\nDica de Prática: "I thought you were at home".' },
  { id: 'f422', level: 'A2', theme: 'Grammar', front: 'Qual é o passado de "Catch" (Apanhar)?', back: 'Caught.\n\nDica de Prática: "He caught the ball".' },
  { id: 'f423', level: 'A2', theme: 'Grammar', front: 'Qual a diferença entre "As... as" e o comparativo normal?', back: 'As... as significa "Tão... quanto" (indica igualdade).\n\nDica de Prática: "My car is as fast as your car".' },
  { id: 'f424', level: 'A2', theme: 'Grammar', front: 'Qual é a diferença entre "Between" e "Among"?', back: 'Between = Entre DUAS coisas/pessoas. Among = Entre VÁRIAS coisas/pessoas.\n\nDica de Prática: "I sat between John and Mary. I found my keys among the papers".' },
  { id: 'f425', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Earn" e "Win"?', back: 'Earn = Ganhar (com esforço/trabalho, ex: salário). Win = Ganhar (sorte ou competição).\n\nDica de Prática: "I earn $2000 a month, but I won the lottery!".' },
  { id: 'f426', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Wear" e "Carry"?', back: 'Wear = Vestir/Usar (roupa, perfume, relógio). Carry = Transportar/Carregar nas mãos.\n\nDica de Prática: "She is wearing a jacket and carrying a heavy bag".' },
  { id: 'f427', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Hope" e "Wait"?', back: 'Hope = Ter esperança/Desejar. Wait = Esperar (tempo).\n\nDica de Prática: "I hope it doesn\'t rain. I will wait for you here".' },
  { id: 'f428', level: 'A2', theme: 'Vocabulary', front: 'Diferença entre "Miss" e "Lose"?', back: 'Miss = Perder (um evento, transporte) ou sentir saudade. Lose = Perder (um objeto, um jogo).\n\nDica de Prática: "I missed the bus and lost my phone".' },
  { id: 'f429', level: 'A2', theme: 'Phrasal Verbs', front: 'O que significa "Find out"?', back: 'Descobrir.\n\nDica de Prática: "We need to find out where they are going".' },
  { id: 'f430', level: 'A2', theme: 'Phrasal Verbs', front: 'O que significa "Grow up"?', back: 'Crescer (referente a pessoas, infância).\n\nDica de Prática: "I grew up in Brazil".' },
  { id: 'f431', level: 'A2', theme: 'Grammar', front: 'O que significa "Both" e "Neither"?', back: 'Both = Ambos (os dois). Neither = Nenhum dos dois.\n\nDica de Prática: "Both of them are my friends. Neither of them speaks French".' },
  { id: 'f432', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Desculpe interromper"?', back: 'Sorry to interrupt.\n\nDica de Prática: "Sorry to interrupt, but you have a phone call".' },
  { id: 'f433', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Crowded"?', back: 'Lotado, cheio de pessoas.\n\nDica de Prática: "The supermarket was very crowded today".' },
  { id: 'f434', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Noisy" e "Quiet"?', back: 'Barulhento / Silencioso.\n\nDica de Prática: "The city is noisy, but the countryside is quiet".' },
  { id: 'f435', level: 'A2', theme: 'Vocabulary', front: 'Como se diz "Preguiçoso" e "Trabalhador"?', back: 'Lazy / Hard-working.\n\nDica de Prática: "My brother is lazy, but I am hard-working".' },
  { id: 'f436', level: 'A2', theme: 'Grammar', front: 'O que significam "Something", "Someone" e "Somewhere"?', back: 'Algo / Alguém / Em algum lugar.\n\nDica de Prática: "There is someone in the house looking for something".' },
  { id: 'f437', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Luggage" ou "Baggage"? É contável?', back: 'Bagagem. É INCONTÁVEL (não se diz "luggages").\n\nDica de Prática: "I have a lot of luggage" (e nunca "many luggages").' },
  { id: 'f438', level: 'A2', theme: 'Grammar', front: 'Como usar "Too" e "Enough"?', back: 'Too = Demais (antes de adjetivo). Enough = Suficiente (depois de adjetivo).\n\nDica de Prática: "The coffee is too hot. It is not cold enough".' },
  { id: 'f439', level: 'A2', theme: 'Vocabulary', front: 'O que significa "Foreigner"?', back: 'Estrangeiro.\n\nDica de Prática: "Many foreigners visit Portugal every year".' },
  { id: 'f440', level: 'A2', theme: 'Collocations', front: 'Diz-se "Make a photo" ou "Take a photo"?', back: 'Take a photo (Tirar uma fotografia).\n\nDica de Prática: "Can you take a photo of us, please?".' },

  // ==========================================
  // NÍVEL B1 (441 - 460)
  // ==========================================
  { id: 'f441', level: 'B1', theme: 'Vocabulary', front: 'Falso cognato: O que significa "Notice"?', back: 'Notar / Reparar / Perceber. (NÃO é notícia; notícia é "News").\n\nDica de Prática: "Did you notice that she cut her hair?".' },
  { id: 'f442', level: 'B1', theme: 'Vocabulary', front: 'Falso cognato: O que significa "Realize"?', back: 'Dar-se conta de / Aperceber-se. (NÃO é realizar um evento; isso seria "Carry out" ou "Hold").\n\nDica de Prática: "I just realized I left my keys at home".' },
  { id: 'f443', level: 'B1', theme: 'Grammar', front: 'Qual é a diferença entre "Don\'t have to" e "Mustn\'t"?', back: 'Don\'t have to = Não é preciso/Não é obrigatório. Mustn\'t = É proibido.\n\nDica de Prática: "You don\'t have to come if you are tired. But you mustn\'t drive drunk".' },
  { id: 'f444', level: 'B1', theme: 'Grammar', front: 'Como se diz "A não ser que"?', back: 'Unless.\n\nDica de Prática: "I won\'t go to the party unless you go with me".' },
  { id: 'f445', level: 'B1', theme: 'Grammar', front: 'Diferença entre "So" e "Such"?', back: 'So + Adjetivo (So beautiful). Such a + Adjetivo + Substantivo (Such a beautiful day).\n\nDica de Prática: "She is so smart! She is such a smart person!".' },
  { id: 'f446', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Give up"?', back: 'Desistir ou parar um hábito.\n\nDica de Prática: "I decided to give up eating junk food".' },
  { id: 'f447', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Take up"?', back: 'Começar um novo hobby, desporto ou atividade.\n\nDica de Prática: "He took up golf last summer".' },
  { id: 'f448', level: 'B1', theme: 'Vocabulary', front: 'O que significa "To afford"?', back: 'Ter capacidade financeira para comprar algo.\n\nDica de Prática: "I can\'t afford to buy a new car this year".' },
  { id: 'f449', level: 'B1', theme: 'Vocabulary', front: 'O que significa "To regret"?', back: 'Arrepender-se.\n\nDica de Prática: "I regret not studying harder for the test".' },
  { id: 'f450', level: 'B1', theme: 'Grammar', front: 'Para que servem os "Relative Pronouns" (Who, Which, That, Whose)?', back: 'Para ligar frases e evitar repetições.\n\nDica de Prática: "The man WHO called you is my uncle".' },
  { id: 'f451', level: 'B1', theme: 'Collocations', front: 'Diz-se "Make a mistake" ou "Do a mistake"?', back: 'Make a mistake (Cometer um erro).\n\nDica de Prática: "Everyone makes mistakes, don\'t worry".' },
  { id: 'f452', level: 'B1', theme: 'Collocations', front: 'Diz-se "Make your best" ou "Do your best"?', back: 'Do your best (Dar o teu melhor).\n\nDica de Prática: "Just do your best in the interview".' },
  { id: 'f453', level: 'B1', theme: 'Vocabulary', front: 'Diferença entre "Rob" e "Steal"?', back: 'Rob = Assaltar (um lugar ou pessoa). Steal = Roubar (um objeto).\n\nDica de Prática: "They robbed the bank and stole a million dollars".' },
  { id: 'f454', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Stubborn"?', back: 'Teimoso.\n\nDica de Prática: "He never changes his mind, he is very stubborn".' },
  { id: 'f455', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Look forward to"?', back: 'Aguardar ansiosamente. O verbo a seguir leva sempre "-ing".\n\nDica de Prática: "I look forward to meeting you".' },
  { id: 'f456', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Put off"?', back: 'Adiar (um evento ou tarefa).\n\nDica de Prática: "They put off the meeting until next week".' },
  { id: 'f457', level: 'B1', theme: 'Phrasal Verbs', front: 'O que significa "Call off"?', back: 'Cancelar.\n\nDica de Prática: "The concert was called off because the singer was sick".' },
  { id: 'f458', level: 'B1', theme: 'Vocabulary', front: 'O que significa "To commute"?', back: 'Fazer o trajeto diário de casa para o trabalho/escola.\n\nDica de Prática: "I commute by train every day".' },
  { id: 'f459', level: 'B1', theme: 'Grammar', front: 'Qual é o uso do "Past Perfect" (Had + Particípio)?', back: 'Indicar que uma ação no passado aconteceu ANTES de outra ação no passado.\n\nDica de Prática: "When I arrived, the train had left".' },
  { id: 'f460', level: 'B1', theme: 'Vocabulary', front: 'O que significa "Frightening"?', back: 'Assustador.\n\nDica de Prática: "That horror movie was truly frightening".' },

  // ==========================================
  // NÍVEL B2 (461 - 480)
  // ==========================================
  { id: 'f461', level: 'B2', theme: 'Grammar', front: 'O que é a "Mixed Conditional"?', back: 'Mistura do passado irreal (If + Past Perfect) com resultado no presente (Would + verbo).\n\nDica de Prática: "If I had studied harder, I would have a better job now".' },
  { id: 'f462', level: 'B2', theme: 'Grammar', front: 'Como se expressa um conselho forte que significa "É melhor..."?', back: 'Had better.\n\nDica de Prática: "You had better leave now, or you will miss the bus".' },
  { id: 'f463', level: 'B2', theme: 'Grammar', front: 'Como dizer "Preferia" (preferência sobre uma ação imediata)?', back: 'Would rather.\n\nDica de Prática: "I would rather stay home than go out tonight".' },
  { id: 'f464', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Put up with"?', back: 'Tolerar, aguentar (algo desagradável).\n\nDica de Prática: "I can\'t put up with his bad behavior anymore".' },
  { id: 'f465', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Look down on"?', back: 'Menosprezar, achar-se superior a alguém.\n\nDica de Prática: "He looks down on people who don\'t have a degree".' },
  { id: 'f466', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Bring up"?', back: 'Trazer um assunto à conversa ou educar/criar uma criança.\n\nDica de Prática: "Don\'t bring up politics at the dinner table".' },
  { id: 'f467', level: 'B2', theme: 'Idioms', front: 'O que significa "Ring a bell"?', back: 'Soar familiar, lembrar vagamente de algo.\n\nDica de Prática: "That name rings a bell, but I can\'t remember his face".' },
  { id: 'f468', level: 'B2', theme: 'Idioms', front: 'O que significa "Hit the sack"?', back: 'Ir dormir / Ir para a cama.\n\nDica de Prática: "I am exhausted, it\'s time to hit the sack".' },
  { id: 'f469', level: 'B2', theme: 'Idioms', front: 'O que significa "Spill the beans"?', back: 'Revelar um segredo.\n\nDica de Prática: "Come on, spill the beans! What did she tell you?".' },
  { id: 'f470', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Overwhelmed"?', back: 'Sobrecarregado (seja por tarefas ou emoções).\n\nDica de Prática: "I am completely overwhelmed with work right now".' },
  { id: 'f471', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Reluctant"?', back: 'Relutante, sem vontade de fazer algo.\n\nDica de Prática: "He was reluctant to accept the new rules".' },
  { id: 'f472', level: 'B2', theme: 'Vocabulary', front: 'O que significa "To take for granted"?', back: 'Não dar valor, assumir que algo estará sempre disponível.\n\nDica de Prática: "We often take our health for granted".' },
  { id: 'f473', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Out of the blue"?', back: 'Inesperadamente, do nada.\n\nDica de Prática: "He called me completely out of the blue".' },
  { id: 'f474', level: 'B2', theme: 'Grammar', front: 'O que expressa a estrutura "Must have + particípio passado"?', back: 'Uma dedução lógica forte sobre algo no passado.\n\nDica de Prática: "The grass is wet. It must have rained".' },
  { id: 'f475', level: 'B2', theme: 'Grammar', front: 'O que expressa a estrutura "Can\'t have + particípio passado"?', back: 'Uma dedução de que algo foi impossível de acontecer no passado.\n\nDica de Prática: "He can\'t have stolen the car, he was with me all night".' },
  { id: 'f476', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Flawless"?', back: 'Sem defeitos, perfeito.\n\nDica de Prática: "Her performance on the piano was flawless".' },
  { id: 'f477', level: 'B2', theme: 'Vocabulary', front: 'O que significa "To bear in mind"?', back: 'Ter em consideração, lembrar-se de um facto importante.\n\nDica de Prática: "Bear in mind that the deadline is strictly on Friday".' },
  { id: 'f478', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Brush up on"?', back: 'Rever ou praticar algo esquecido (ex: uma língua).\n\nDica de Prática: "I need to brush up on my Spanish before the trip".' },
  { id: 'f479', level: 'B2', theme: 'Phrasal Verbs', front: 'O que significa "Catch up with"?', back: 'Pôr a conversa em dia ou alcançar o nível de alguém.\n\nDica de Prática: "Let\'s get coffee and catch up!".' },
  { id: 'f480', level: 'B2', theme: 'Vocabulary', front: 'O que significa "Breathtaking"?', back: 'De cortar a respiração, incrivelmente bonito/impressionante.\n\nDica de Prática: "The view from the top of the mountain was breathtaking".' },

  // ==========================================
  // NÍVEL C1 (481 - 500)
  // ==========================================
  { id: 'f481', level: 'C1', theme: 'Grammar', front: 'O que exige a expressão "Not only..." no início de frase?', back: 'Inversão do sujeito com o verbo auxiliar.\n\nDica de Prática: "Not only WAS HE late, but he also forgot the documents".' },
  { id: 'f482', level: 'C1', theme: 'Grammar', front: 'Como se usa "No sooner... than"?', back: 'Para dizer que algo aconteceu logo após outra coisa. Exige inversão e Past Perfect.\n\nDica de Prática: "No sooner HAD I ARRIVED than the phone rang".' },
  { id: 'f483', level: 'C1', theme: 'Grammar', front: 'O que é uma Cleft Sentence (ex: "It was...")?', back: 'Uma frase estruturada para dar ênfase a uma informação específica.\n\nDica de Prática: "It was JOHN who sent the email" (Foco em quem enviou, não no quê).' },
  { id: 'f484', level: 'C1', theme: 'Grammar', front: 'O que é uma Cleft Sentence iniciada com "What..."?', back: 'Enfatiza a ação, o sentimento ou a necessidade do sujeito.\n\nDica de Prática: "What I need right now is a long holiday".' },
  { id: 'f485', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ubiquitous"?', back: 'Omnipresente, encontrado em todo o lado.\n\nDica de Prática: "Smartphones have become ubiquitous in modern society".' },
  { id: 'f486', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ephemeral"?', back: 'Efémero, que dura muito pouco tempo.\n\nDica de Prática: "Fame on the internet is often ephemeral".' },
  { id: 'f487', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Meticulous"?', back: 'Extremamente detalhista e cuidadoso.\n\nDica de Prática: "She is a meticulous researcher".' },
  { id: 'f488', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Pragmatic"?', back: 'Pragmático, que lida com problemas de forma realista e prática.\n\nDica de Prática: "We need a pragmatic solution to this crisis".' },
  { id: 'f489', level: 'C1', theme: 'Vocabulary', front: 'O que significa "Ambiguous"?', back: 'Ambíguo, aberto a mais de uma interpretação.\n\nDica de Prática: "His answer was completely ambiguous".' },
  { id: 'f490', level: 'C1', theme: 'Collocations', front: 'O que significa "Stark contrast"?', back: 'Um contraste extremo, nítido e evidente.\n\nDica de Prática: "The poverty here is in stark contrast to the wealth of the capital".' },
  { id: 'f491', level: 'C1', theme: 'Collocations', front: 'O que é "A sweeping generalization"?', back: 'Uma generalização excessiva e muitas vezes incorreta.\n\nDica de Prática: "Saying all millennials are lazy is a sweeping generalization".' },
  { id: 'f492', level: 'C1', theme: 'Collocations', front: 'O que significa "Blatant disregard"?', back: 'Desrespeito descarado ou óbvio por regras.\n\nDica de Prática: "He acted with blatant disregard for safety regulations".' },
  { id: 'f493', level: 'C1', theme: 'Idioms', front: 'O que significa "Play devil\'s advocate"?', back: 'Assumir uma opinião contrária apenas para testar argumentos ou animar um debate.\n\nDica de Prática: "I agree, I\'m just playing devil\'s advocate".' },
  { id: 'f494', level: 'C1', theme: 'Idioms', front: 'O que significa "Bite the bullet"?', back: 'Enfrentar uma situação difícil ou desagradável com coragem porque é inevitável.\n\nDica de Prática: "I\'ll just have to bite the bullet and pay the fine".' },
  { id: 'f495', level: 'C1', theme: 'Idioms', front: 'O que significa "Burn your bridges"?', back: 'Destruir a possibilidade de retornar a uma situação (ex: cortar relações ao sair de um emprego).\n\nDica de Prática: "Be polite when you resign, don\'t burn your bridges".' },
  { id: 'f496', level: 'C1', theme: 'Idioms', front: 'O que significa "A blessing in disguise"?', back: 'Um mal que vem por bem (algo aparentemente mau que acaba por ser positivo).\n\nDica de Prática: "Losing that awful job was a blessing in disguise".' },
  { id: 'f497', level: 'C1', theme: 'Idioms', front: 'O que significa "Beat around the bush"?', back: 'Andar com rodeios, evitar ir direto ao assunto.\n\nDica de Prática: "Stop beating around the bush and tell me what happened!".' },
  { id: 'f498', level: 'C1', theme: 'Grammar', front: 'O que é exigido pelo Subjuntivo após "It is essential that..."?', back: 'O verbo na sua forma base, sem conjugação (sem "to", sem "s" no final).\n\nDica de Prática: "It is essential that he BE informed immediately".' },
  { id: 'f499', level: 'C1', theme: 'Grammar', front: 'O que significa uma "Participle Clause" como: "Having finished the report, I left"?', back: 'Indica que a ação de "terminar o relatório" foi concluída antes da ação principal de "sair".\n\nDica de Prática: Substitui a frase "After I had finished the report...".' },
  { id: 'f500', level: 'C1', theme: 'Phrasal Verbs', front: 'O que significa "Boil down to"?', back: 'Resumir-se a / Reduzir-se ao aspeto mais fundamental.\n\nDica de Prática: "The whole debate boils down to a question of money".' }
];

export default flashcardsData;